insert into public.exercises
  (slug, domain, modality, title, summary, parent_guide, difficulty, age_min, age_max, duration_minutes, content, is_builtin)
values
('ar-gymnastika-1', 'articulation', 'guided', 'Gymnastika pre jazýček', 'Oromotorická gymnastika pred zrkadlom rozvíja pohyblivosť a koordináciu jazyka, pier a líc aj cielené ovládanie výdychového prúdu — motorický základ správnej artikulácie hlások.', 'Sadnite si s dieťaťom pred zrkadlo tak, aby ste sa v ňom obaja videli. Každý cvik najprv sami pomaly predveďte a až potom cvičte spolu — dieťa napodobňuje vás aj svoj obraz v zrkadle. Chváľte snahu, nie dokonalosť: „Vidím, že tvoj jazýček dnes poriadne cvičí!“ Ak cvik nejde, zasmejte sa spolu a skúste ho ešte raz pomalšie.', 1, 5, 8, 8, '{"type":"guided_steps","intro":"Tvoj jazýček je športovec — poď s ním do telocvične pred zrkadlom!","steps":[{"kicker":"Krok 1 · Naladenie","title":"Ako sa dnes cítiš?","body":"Sadnite si spolu pred zrkadlo a povedzte: „Dnes ideme cvičiť s jazýčkom ako ozajstní športovci. Ako sa cítiš pred tréningom?“ Nechajte dieťa vybrať, čo cíti. Potom si spolu povedzte plán tréningu: najprv výťah, potom žabka s rybkou, fúkanie a nakoniec maškrtenie.","choices":["Teším sa 😊","Som zvedavý/zvedavá 🤔","Trochu sa hanbím 😳","Dnes sa mi nechce 😴"],"tip":"Každý pocit je v poriadku. Ak sa dieťaťu nechce, dohodnite sa len na dvoch cvikoch — chuť často príde počas cvičenia."},{"kicker":"Krok 2 · Rozcvička","title":"Jazýček — výťah","body":"Povedzte: „Tvoj jazýček je výťah. Ide hore k nosu… a pomaly dole k brade.“ Predveďte cvik a potom ho spolu zopakujte päťkrát. Ústa sú otvorené a brada sa nehýbe — pracuje len jazyk.","tip":"Ak sa hýbe celá brada, jemne ju dieťaťu podoprite prstom. Nikdy necvičte za dieťa — len znova pomaly predveďte."},{"kicker":"Krok 3 · Pery","title":"Žabka a rybka","body":"Povedzte: „Teraz sa hráme na zvieratká. Žabka sa široko usmieva — ííí. Rybka špúli pery dopredu — úúú.“ Striedajte úsmev a špúlenie päťkrát, pomaly a poriadne.","tip":"Sledujte v zrkadle, či je úsmev naozaj široký a špúlenie naozaj dopredu. Pomáha striedať cviky na povel: „žabka — rybka“."},{"kicker":"Krok 4 · Fúkanie","title":"Veterná súťaž","body":"Položte na stôl vatovú guličku alebo malý kúsok papiera. Povedzte: „Nadýchni sa nosom a fúkni, nech gulička dobehne na druhý koniec stola.“ Skúste tri jazdy — raz silno, raz jemne, raz čo najdlhšie.","fields":[{"label":"Čo išlo pri fúkaní ťažko?","placeholder":"napr. krátky výdych, nafukovanie líc, fúkanie nosom"}],"tip":"Nádych nosom, výdych ústami. Ak dieťa nafukuje líca, jemne mu ich pridržte prstami a skúste znova."},{"kicker":"Krok 5 · Maškrtenie","title":"Maškrtný jazýček","body":"Povedzte: „Predstav si, že máš okolo pier medík. Obliž si pery pekne dookola — najprv na jednu stranu, potom na druhú.“ Ak chcete, dajte dieťaťu na hornú peru ozajstnú kvapku medu alebo džemu — jazýček ju musí nájsť.","tip":"Pohyb má byť pomalý a plynulý. Radšej raz poriadne dookola než päťkrát narýchlo."},{"kicker":"Krok 6 · Zhodnotenie","title":"Malý športovec hodnotí","body":"Spýtajte sa: „Ktorý cvik bol pre teba najťažší? A ktorý ti išiel najlepšie?“ Zapíšte, čo dieťa povie. Na záver povedzte spolu nahlas: „Moja pusa cvičila a je silnejšia!“","fields":[{"label":"Ktorý cvik išiel dieťaťu najťažšie?","placeholder":"napr. výťah hore k nosu"},{"label":"Čo sa dnes podarilo?","placeholder":"napr. udržalo široký úsmev, fúkalo dlho a jemne"}],"tip":"Nechajte najprv hodnotiť dieťa. Vaše pozorovanie doplňte až potom — a vždy začnite tým, čo sa podarilo."}]}'::jsonb, true),
('ar-hlaska-l-1', 'articulation', 'speech', 'Slová s hláskou L', 'Fixácia hlásky L v slovách v iniciálnej, mediálnej a finálnej pozícii s oporou o správne artikulačné postavenie — špička jazyka na ďasne za hornými rezákmi.', 'Predveďte slovo pomaly a zreteľne, hlásku L mierne pretiahnite: llllopta. Dieťa slovo zopakuje po vás. Ak L nepočuť, pripomeňte: „Jazýček vyskočí hore za horné zúbky — a spustí sa, keď povieš L.“ Ťažšie slovo pokojne rozdeľte na slabiky a skladajte ho spolu po častiach.', 1, 5, 9, 5, '{"type":"speech_items","intro":"Jazýček vyskočí za horné zúbky a povie L. Skús to v každom slove!","items":[{"text":"lopta","emoji":"⚽","tip":"Pred prvým slovom si spolu precvičte samotné „lll“ — špička jazyka sa opiera za horné zuby."},{"text":"lampa","emoji":"💡"},{"text":"lyžica","emoji":"🥄"},{"text":"lietadlo","emoji":"✈️","tip":"Slovo má L dvakrát — pomôže rozdelenie na slabiky: lie-ta-dlo."},{"text":"včela","emoji":"🐝"},{"text":"škola","emoji":"🏫"},{"text":"balón","emoji":"🎈"},{"text":"mlieko","emoji":"🥛","tip":"L je hneď za M — skúste najprv pomaly: m-lie-ko."},{"text":"stôl","tip":"L na konci slova býva ťažšie. Nech dieťa slovo dopovie pomaly a jazýček nechá hore: stôôôl."},{"text":"anjel","emoji":"😇"}]}'::jsonb, true),
('ar-hlaska-r-2', 'articulation', 'speech', 'Slová s hláskou R', 'Fixácia vibrantu R v slovách s postupnosťou od najľahšej pozície po spoluhláskach T a D cez mediálnu pozíciu až po iniciálnu a finálnu; opora o prípravné „trrr“.', 'Najprv si spolu naštartujte motorček: „trrr — drrr“. Potom predveďte slovo a v R mierne zavrčte: trrráva. Dieťa opakuje po vás. Ak R nejde, vráťte sa k motorčeku a slovo rozdeľte na slabiky: trá-va. Nevyžadujte dokonalé R — pochváľte každé zavrčanie a pokus.', 2, 6, 10, 5, '{"type":"speech_items","intro":"Naštartuj motorček — trrr! — a rozbehni ho v slovách.","items":[{"text":"drevo","emoji":"🪵","tip":"R po D je najľahšie. Začnite motorčekom „drrr“ a pridajte zvyšok slova: drrr-evo."},{"text":"tráva","emoji":"🌿","tip":"Po T ide R takmer samo: trrr-áva."},{"text":"traktor","emoji":"🚜","tip":"Slovo má R dvakrát — najprv pomaly po slabikách: trak-tor."},{"text":"trúbka","emoji":"🎺"},{"text":"mrkva","emoji":"🥕"},{"text":"more","emoji":"🌊"},{"text":"hora","emoji":"⛰️"},{"text":"koruna","emoji":"👑"},{"text":"ryba","emoji":"🐟","tip":"R na začiatku slova je najťažšie — pomôže najprv samostatné zavrčanie: rrr-yba."},{"text":"syr","emoji":"🧀","tip":"R na konci nechajte doznieť: syrrr."}]}'::jsonb, true),
('ar-sykavky-s-c-z-1', 'articulation', 'speech', 'Hadík syčí — S, C, Z', 'Fixácia ostrej sykavkovej rady S, C, Z v slovách; kontrola úsmevového postavenia pier a opory jazyka pri dolných rezákoch ako prevencia zámeny s tupou radou.', 'Predveďte slovo so zreteľnou sykavkou: ssssyr. Pripomínajte dieťaťu kúzelné pravidlo: „Usmej sa a jazýček schovaj dole za spodné zúbky.“ Ak sykavka znie tupo ako š, ukážte si spolu v zrkadle široký úsmev a slovo skúste znova.', 1, 5, 9, 5, '{"type":"speech_items","intro":"Usmej sa ako hadík — sss! — a jazýček schovaj za spodné zúbky.","items":[{"text":"syr","emoji":"🧀","tip":"Skontrolujte úsmev a jazyk dole za spodnými zubami: ssss-yr."},{"text":"sova","emoji":"🦉"},{"text":"slon","emoji":"🐘"},{"text":"mesiac","emoji":"🌙","tip":"Slovo končí na C — krátke a ostré ako lusknutie prstami."},{"text":"cibuľa","emoji":"🧅","tip":"C na začiatku je krátke ako tikanie hodín: c-c-c — cibuľa."},{"text":"citrón","emoji":"🍋"},{"text":"ovca","emoji":"🐑"},{"text":"zajac","emoji":"🐇","tip":"Z bzučí ako mucha: zzz-ajac. A na konci pozor na krátke C."},{"text":"zebra","emoji":"🦓"},{"text":"koza","emoji":"🐐"}]}'::jsonb, true),
('ar-sykavky-s-z-c-2', 'articulation', 'speech', 'Vláčik šuští — Š, Ž, Č', 'Fixácia tupej sykavkovej rady Š, Ž, Č v slovách; nácvik labializácie (pery vysunuté vpred) a mierneho stiahnutia jazyka dozadu.', 'Predveďte slovo so zreteľnou sykavkou: šššál. Pripomeňte dieťaťu: „Pery vystrč dopredu ako komín — šššš ako vláčik.“ Rozdiel medzi s a š si ukážte v zrkadle: pri s je úsmev, pri š komín. Ak slovo znie ostro, vráťte sa ku komínu a skúste znova.', 2, 6, 10, 5, '{"type":"speech_items","intro":"Vystrč pery dopredu ako komín a šušti ako vláčik — šš, šš!","items":[{"text":"šál","emoji":"🧣","tip":"Pery dopredu ako komín: šššš-ál."},{"text":"šaty","emoji":"👗"},{"text":"myš","emoji":"🐭","tip":"Š na konci nechajte doznieť: myšššš."},{"text":"žaba","emoji":"🐸","tip":"Ž bzučí a pery ostávajú dopredu: žžž-aba."},{"text":"žirafa","emoji":"🦒"},{"text":"ruža","emoji":"🌹"},{"text":"čiapka","emoji":"🧢","tip":"Č je krátke a razantné — ako keď sa vláčik rozbieha: č-č-č."},{"text":"čaj","emoji":"🍵"},{"text":"mačka","emoji":"🐱"},{"text":"kľúč","emoji":"🔑","tip":"Č na konci sa nesmie stratiť — nech dieťa slovo dopovie celé a č zaznie krátko a zreteľne."}]}'::jsonb, true),
('ar-miesanie-sykaviek-3', 'articulation', 'speech', 'Popletené sykavky', 'Diferenciácia ostrých a tupých sykaviek (s/š, c/č, z/ž) v slovách a krátkych vetách — záverečný krok fixácie pred automatizáciou v spontánnej reči.', 'Čítajte pomaly a zreteľne, sykavky mierne pretiahnite. Pri chybe nehovorte hneď správne znenie — spýtajte sa: „Bol tam hadík (s) alebo vláčik (š)?“ a nechajte dieťa opraviť sa samo. Dlhšiu vetu rozdeľte na časti a skladajte ju po slovách.', 3, 7, 10, 6, '{"type":"speech_items","intro":"Pozor, hadík a vláčik sa pomiešali! Rozoznáš, kedy syčíš a kedy šuštíš?","items":[{"text":"suší","tip":"Jedno slovo, obe sykavky: najprv úsmev (s), potom komín (š) — su-ší."},{"text":"šesť","emoji":"6️⃣","tip":"Najprv komín (š), potom úsmev (s) a na konci mäkké ť: šesť."},{"text":"slnečnica","emoji":"🌻","tip":"Pomaly po slabikách: sl-neč-ni-ca."},{"text":"časopis","emoji":"📰"},{"text":"žiacka taška","emoji":"🎒","tip":"Dve slová, tri sykavky — pomaly: žiac-ka taš-ka."},{"text":"čerstvý syr","emoji":"🧀"},{"text":"Saša suší šaty.","tip":"Vetu najprv po slovách: Sa-ša — su-ší — ša-ty."},{"text":"Zuzka číta časopis."},{"text":"Mačka sedí na streche."},{"text":"Šesť sivých myšiek sa smeje.","tip":"Najťažšia veta — pokojne dvakrát pomaly a až tretí raz normálnym tempom."}]}'::jsonb, true),
('ar-dlhe-kratke-2', 'articulation', 'speech', 'Krátke a dlhé — sud či súd?', 'Diferenciácia vokalickej kvantity na minimálnych pároch; dieťa produkuje oba členy páru a uvedomuje si dištinktívnu funkciu dĺžky samohlásky.', 'Prečítajte obe slová a dĺžku výrazne pretiahnite: sud — súúúd. Porozprávajte sa, čo ktoré slovo znamená. Potom dieťa povie oba tvary — pri dlhej slabike môžete spolu roztiahnuť ruky ako harmoniku. Spýtajte sa: „Počuješ, ktoré slovo je dlhšie?“', 2, 6, 10, 6, '{"type":"speech_items","intro":"Niektoré slová sa natiahnu ako guma — a hneď znamenajú niečo úplne iné!","items":[{"text":"sud → súd","emoji":"🛢️","tip":"Sud je drevená nádoba, súd je budova, kde pracuje sudca. Dĺžka mení význam!"},{"text":"latka → látka","emoji":"🧵","tip":"Latka je drevená tyčka, látka je textil, z ktorého sa šijú šaty."},{"text":"pas → pás","emoji":"🛂","tip":"Pas potrebujeme na cestovanie, pás máme okolo brucha."},{"text":"vila → víla","emoji":"🧚","tip":"Vila je veľký dom, víla je rozprávková bytosť s krídelkami."},{"text":"rad → rád","emoji":"🚶","tip":"Rad je, keď ľudia stoja za sebou. Rád znamená, že sa nám niečo páči: mám ťa rád."},{"text":"krik → krík","emoji":"🌿","tip":"Krik je hlasné volanie, krík je malý ker na záhrade."},{"text":"pila → píla","emoji":"🪚","tip":"Pila povieme o niekom, kto pil: Ema pila vodu. Píla je nástroj na rezanie dreva."},{"text":"kura → kúra","emoji":"🐔","tip":"Kura behá po dvore, kúra je liečenie — napríklad vitamínová kúra."}]}'::jsonb, true),
('ar-jazykolamy-3', 'articulation', 'speech', 'Jazykolamy pre šikovné jazýčky', 'Automatizácia artikulácie v náročných hláskových sekvenciách; jazykolamy precvičujú presnosť, tempo a koartikuláciu pri plnej záťaži rečovej motoriky.', 'Každý jazykolam najprv prečítajte pomaly po slabikách a dieťa ho opakuje po častiach. Až potom skúste celý naraz — najprv pomaly, potom o kúsok rýchlejšie. Zamotanie jazyka je súčasť hry: pomýľte sa občas aj vy a spolu sa na tom zasmejte.', 3, 7, 10, 7, '{"type":"speech_items","intro":"Pozor, tieto vety radi zamotávajú jazyk! Najprv pomaličky, potom rýchlo.","items":[{"text":"Mama má Emu, Ema má mamu.","emoji":"👩","tip":"Na rozohriatie — tento zvládne dieťa aj naozaj rýchlo."},{"text":"Guľôčka v jamôčke, v jamôčke guľôčka.","emoji":"⚪","tip":"Mäkké ľ a vokáň ô — pomaly: gu-ľôč-ka v ja-môč-ke."},{"text":"Šašo suší osušku.","emoji":"🤡","tip":"Striedajú sa š a s — komín a úsmev."},{"text":"Ryba, rak, rebrík, rúra, robot.","emoji":"🐟","tip":"Prehliadka slov s R — pred štartom naštartujte motorček: trrr."},{"text":"Pán kaplán v kaplnke plakal.","emoji":"⛪","tip":"Skupiny pl a kl chcú pomalý štart — najprv po slabikách."},{"text":"V našej peci myši pištia, v našej peci psík spí.","emoji":"🐭","tip":"Dlhá veta — rozdeľte ju na dve polovice a potom spojte."},{"text":"Strýc Šusták šuštal šušťákom.","emoji":"🧥","tip":"Samé š — pery držte celý čas dopredu ako komín."},{"text":"Tristo strieborných striekačiek striekalo cez tristo strieborných striech.","emoji":"💦","tip":"Kráľ jazykolamov! Stačí povedať raz pomaly a čisto — rýchlosť nie je cieľ."}]}'::jsonb, true),
('at-ciselny-rad-1', 'attention', 'interactive', 'Číselný rad do 10', 'Nácvik riadenej zrakovej pozornosti a sebakontroly podľa metodiky Achutinovej a Pylajevovej — číselný rad slúži ako externá opora usporiadania činnosti.', 'Sadnite si vedľa dieťaťa a povedzte: „Ťukaj na čísla pekne po poriadku a každé nahlas prečítaj.“ Ak dieťa zaváha, opýtajte sa: „Ktoré číslo príde po trojke?“ a spolu rátajte nahlas od jednotky. Neukazujte správne číslo prstom — počkajte, kým ho dieťa nájde samo.', 1, 5, 7, 4, '{"type":"number_track","intro":"Ťukaj na čísla po poriadku, od najmenšieho po najväčšie. Každé číslo povedz nahlas.","rounds":[{"from":1,"to":4},{"from":1,"to":6},{"from":1,"to":8},{"from":1,"to":10}]}'::jsonb, true),
('at-ciselny-rad-2', 'attention', 'interactive', 'Číselný rad s rušičmi', 'Selektívna pozornosť a inhibícia rušivých podnetov na číselnom rade do 15 — dieťa udržiava cieľ činnosti napriek distraktorom mimo hľadaného rozsahu.', 'Povedzte dieťaťu: „Na obrazovke sú aj čísla, ktoré do radu nepatria — tie nechaj tak.“ Keď zaváha, opýtajte sa: „Aké číslo teraz hľadáš? Je väčšie, alebo menšie ako to posledné?“ Pri chybe pokojne povedzte: „Nič sa nedeje, skús ešte raz a rátaj nahlas.“', 2, 6, 9, 5, '{"type":"number_track","intro":"Pozor, medzi číslami sa skrývajú aj také, ktoré do radu nepatria. Ťukaj len na správne čísla, pekne po poriadku.","rounds":[{"from":1,"to":10,"distractors":[12,14]},{"from":1,"to":12,"distractors":[14,15]},{"from":1,"to":14,"distractors":[16,18]},{"from":1,"to":15,"distractors":[17,19]}]}'::jsonb, true),
('at-ciselny-rad-3', 'attention', 'interactive', 'Číselný rad odzadu', 'Zostupný číselný rad s distraktormi rozvíja flexibilitu pozornosti, pracovnú pamäť a inhibičnú kontrolu pri zmene zaužívaného smeru rátania.', 'Najprv spolu nahlas rátajte odzadu: desať, deväť, osem… Potom povedzte: „Teraz pôjdeš odzadu ty — od najväčšieho čísla k najmenšiemu. Čísla, ktoré do radu nepatria, nechaj tak.“ Ak sa dieťa stratí, opýtajte sa: „Ktoré číslo je o jedno menšie?“ a doprajte mu čas.', 3, 7, 10, 6, '{"type":"number_track","intro":"Dnes to otočíme — ťukaj na čísla odzadu, od najväčšieho po najmenšie. A pozor na čísla, ktoré do radu nepatria!","rounds":[{"from":1,"to":10,"reverse":true,"distractors":[11,13]},{"from":1,"to":12,"reverse":true,"distractors":[14,15]},{"from":5,"to":15,"reverse":true,"distractors":[1,3]},{"from":1,"to":15,"reverse":true,"distractors":[17,18]}]}'::jsonb, true),
('at-najdi-ineho-1', 'attention', 'interactive', 'Nájdi iný obrázok', 'Zraková diferenciácia a selektívna pozornosť — vyhľadanie odlišného podnetu v rade rovnakých; základ pre neskoršie rozlišovanie grafém.', 'Prečítajte otázku a nechajte dieťa pozerať sa v pokoji. Ak si nie je isté, povedzte: „Porovnaj obrázky po dvojiciach — ktoré dva sú úplne rovnaké?“ Nech dieťa svoj výber vždy povie nahlas celou vetou: „Iný je banán, lebo ostatné sú jablká.“', 1, 5, 7, 4, '{"type":"choice","intro":"Pozri sa pozorne. Tri obrázky sú úplne rovnaké a jeden sa odlišuje.","items":[{"prompt":"Ktorý obrázok je iný ako ostatné?","options":[{"label":"jablko","emoji":"🍎"},{"label":"jablko","emoji":"🍎"},{"label":"jablko","emoji":"🍎"},{"label":"banán","emoji":"🍌","correct":true}],"hint":"Pozri sa na farby a tvary. Ktoré tri obrázky sú úplne rovnaké?"},{"prompt":"Ktorý obrázok je iný ako ostatné?","options":[{"label":"pes","emoji":"🐶"},{"label":"mačka","emoji":"🐱","correct":true},{"label":"pes","emoji":"🐶"},{"label":"pes","emoji":"🐶"}],"hint":"Sú tu tri rovnaké zvieratká. Ktoré zvieratko medzi ne nepatrí?"},{"prompt":"Ktorý obrázok je iný ako ostatné?","options":[{"label":"mesiac","emoji":"🌙","correct":true},{"label":"hviezda","emoji":"⭐"},{"label":"hviezda","emoji":"⭐"},{"label":"hviezda","emoji":"⭐"}],"hint":"Nájdi najprv obrázky, ktoré sú úplne rovnaké. Ktorý zostal sám?"},{"prompt":"Ktorý obrázok je iný ako ostatné?","options":[{"label":"auto","emoji":"🚗"},{"label":"auto","emoji":"🚗"},{"label":"bicykel","emoji":"🚲","correct":true},{"label":"auto","emoji":"🚗"}],"hint":"Prezri si obrázky pekne zaradom, jeden po druhom. Čo sa opakuje?"},{"prompt":"Ktorý obrázok je iný ako ostatné?","options":[{"label":"kvet","emoji":"🌸"},{"label":"kvet","emoji":"🌸"},{"label":"kvet","emoji":"🌸"},{"label":"hríb","emoji":"🍄","correct":true}],"hint":"Ktoré tri obrázky patria do jednej skupinky?"},{"prompt":"Ktorý obrázok je iný ako ostatné?","options":[{"label":"žaba","emoji":"🐸","correct":true},{"label":"ryba","emoji":"🐟"},{"label":"ryba","emoji":"🐟"},{"label":"ryba","emoji":"🐟"}],"hint":"Skús to od konca — porovnaj najprv posledné tri obrázky."},{"prompt":"Ktorý obrázok je iný ako ostatné?","options":[{"label":"lopta","emoji":"⚽"},{"label":"lopta","emoji":"⚽"},{"label":"balón","emoji":"🎈","correct":true},{"label":"lopta","emoji":"⚽"}],"hint":"Tri obrázky sú úplne rovnaké — nájdi najprv tie."},{"prompt":"Ktorý obrázok je iný ako ostatné?","options":[{"label":"motýľ","emoji":"🦋"},{"label":"lienka","emoji":"🐞","correct":true},{"label":"motýľ","emoji":"🦋"},{"label":"motýľ","emoji":"🦋"}],"hint":"Pozri sa pozorne na krídla a bodky. Ktorý obrázok vidíš len raz?"}]}'::jsonb, true),
('at-spocitaj-tvary-2', 'attention', 'interactive', 'Spočítaj obrázky', 'Selektívne počítanie cieľových podnetov v rade rozvíja distribúciu pozornosti, systematické prehľadávanie zľava doprava a sebakontrolu pri rátaní.', 'Ukážte dieťaťu riadok obrázkov a prečítajte otázku. Naučte ho ukazovať prstom na každý hľadaný obrázok a rátať nahlas: jeden, dva, tri… Ak sa pomýli, povedzte: „Skús to ešte raz a rátaj pomalšie.“ Výsledok nech vyberie vždy samo.', 2, 6, 9, 5, '{"type":"choice","intro":"Rátame obrázky v riadku. Ukazuj si prstom a rátaj nahlas.","items":[{"prompt":"🔺🔵🔺⭐🔺🔵 — Koľko je 🔺?","options":[{"label":"dva","emoji":"2️⃣"},{"label":"tri","emoji":"3️⃣","correct":true},{"label":"štyri","emoji":"4️⃣"}],"hint":"Rátaj pomaly zľava doprava a každý 🔺 si ukáž prstom."},{"prompt":"🟢🟡🟢🟢🟡 — Koľko je 🟡?","options":[{"label":"dva","emoji":"2️⃣","correct":true},{"label":"tri","emoji":"3️⃣"},{"label":"štyri","emoji":"4️⃣"}],"hint":"Hľadáš len žlté koliesko. Ostatné farby nechaj tak."},{"prompt":"⭐🌙⭐⭐🌙⭐ — Koľko je ⭐?","options":[{"label":"tri","emoji":"3️⃣"},{"label":"päť","emoji":"5️⃣"},{"label":"štyri","emoji":"4️⃣","correct":true}],"hint":"Pri každej hviezde povedz číslo nahlas. Mesiačiky preskoč."},{"prompt":"🔵🔵🔺🔵🔺🔵 — Koľko je 🔵?","options":[{"label":"štyri","emoji":"4️⃣","correct":true},{"label":"tri","emoji":"3️⃣"},{"label":"päť","emoji":"5️⃣"}],"hint":"Začni úplne vľavo a nepreskoč ani jedno koliesko."},{"prompt":"🟥🟨🟥🟥🟨🟥🟥 — Koľko je 🟥?","options":[{"label":"štyri","emoji":"4️⃣"},{"label":"päť","emoji":"5️⃣","correct":true},{"label":"šesť","emoji":"6️⃣"}],"hint":"Rátaj len červené štvorčeky. Pri každom na chvíľu zastav prst."},{"prompt":"🐤🐟🐤🐟🐟 — Koľko je 🐟?","options":[{"label":"tri","emoji":"3️⃣","correct":true},{"label":"dva","emoji":"2️⃣"},{"label":"štyri","emoji":"4️⃣"}],"hint":"Rátaš len rybky, kuriatka nechaj tak. Rátaj nahlas."},{"prompt":"🍓🍇🍓🍇🍓🍇🍇 — Koľko je 🍇?","options":[{"label":"päť","emoji":"5️⃣"},{"label":"tri","emoji":"3️⃣"},{"label":"štyri","emoji":"4️⃣","correct":true}],"hint":"Ukazuj prstom len na strapce hrozna a pri každom povedz číslo."},{"prompt":"🔺🔺🔵🔺🔵🔺🔺 — Koľko je 🔺?","options":[{"label":"päť","emoji":"5️⃣","correct":true},{"label":"štyri","emoji":"4️⃣"},{"label":"šesť","emoji":"6️⃣"}],"hint":"Riadok je dlhý — rátaj pomaly a skontroluj sa ešte raz od začiatku."}]}'::jsonb, true),
('at-pocuvaj-a-tlieskaj-1', 'attention', 'guided', 'Počúvaj a tlieskaj', 'Sluchová selektívna pozornosť s motorickou odpoveďou typu go/no-go — dieťa reaguje len na cieľovú kategóriu slov a inhibuje reakciu na ostatné podnety.', 'Čítajte slová pomaly a zreteľne, medzi slovami počkajte dve sekundy. Pred prvým kolom si hru vyskúšajte na dvoch slovách: stôl — ruky sú ticho, mačka — tlesk. Pri chybe nekomentujte, len pokojne čítajte ďalej; dieťa sa zvyčajne opraví samo pri ďalšom slove. Na záver pochváľte konkrétne, čo sa podarilo.', 1, 5, 8, 6, '{"type":"guided_steps","intro":"Zahráme sa na pozorné uši — tleskneš vždy, keď začuješ zvieratko.","steps":[{"kicker":"Krok 1 · Príprava","title":"Vysvetlíme si hru","body":"Povedzte dieťaťu: „Budem ti pomaly čítať slová. Vždy, keď začuješ zvieratko, tleskni. Pri ostatných slovách sú ruky ticho.“ Vyskúšajte si to na dvoch slovách: stôl (ruky ticho) a mačka (tlesk). Potom sa opýtajte: „Ako sa cítiš pred hrou?“","choices":["Teším sa 😊","Cítim sa pokojne 😌","Zaujíma ma to 🤔","Trochu sa bojím 😕"],"tip":"Nechajte dieťa vybrať pocit bez komentára — každý pocit je v poriadku."},{"kicker":"Krok 2 · Plán","title":"Vyber si, čo ti pomôže","body":"Opýtajte sa dieťaťa: „Čo ti pomôže dobre počúvať?“ Nechajte ho vybrať si stratégiu a spolu ju nahlas zopakujte.","choices":["Sedím pokojne 🧘","Pozorne počúvam každé slovo 👂","Ruky mám pripravené na tlesk 🙌","Poviem si: čakám na zvieratko 🐾"],"tip":"Stratégiu vyberá dieťa — vy ju len nahlas zopakujete."},{"kicker":"Krok 3 · Kolo 1","title":"Prvé kolo","body":"Čítajte pomaly, s prestávkou po každom slove: lopta — mačka — stôl — pes — kvet — sova — topánka — kôň.","tip":"Zvieratá sú štyri: mačka, pes, sova, kôň. Ak dieťa tleskne inde, nekomentujte to — pokojne čítajte ďalej. Nikdy neriešte úlohu za dieťa.","fields":[{"label":"Koľko zo štyroch zvierat dieťa zachytilo?","placeholder":"napr. 3 zo 4"}]},{"kicker":"Krok 4 · Kolo 2","title":"Druhé kolo — dlhší rad","body":"Čítajte o kúsok rýchlejšie: slnko — ryba — kniha — zajac — auto — žaba — mrak — veverička — dvere — medveď.","tip":"Zvierat je päť: ryba, zajac, žaba, veverička, medveď. Ak sa dieťa pomýli, nechajte ho prísť na to samo pri ďalšom slove.","fields":[{"label":"Koľko z piatich zvierat dieťa zachytilo?","placeholder":"napr. 4 z 5"}]},{"kicker":"Krok 5 · Reflexia","title":"Ako sa ti počúvalo?","body":"Opýtajte sa dieťaťa: „Čo ti pomáhalo počúvať pozorne? Ktoré slovo ťa skoro nachytalo?“ Odpovede zapíšte vlastnými slovami dieťaťa.","tip":"Počkajte na odpoveď v tichu — aj dlhšia pauza je v poriadku.","fields":[{"label":"Čo dieťaťu pomáhalo sústrediť sa?","placeholder":"napr. zatvorilo si oči a počúvalo"},{"label":"Pri ktorom slove zaváhalo?","placeholder":"napr. pri slove mrak"}]},{"kicker":"Krok 6 · Ukotvenie","title":"Pochvala a veta na záver","body":"Pochváľte konkrétne, napríklad: „Tvoje ruky pekne počkali na zvieratko a tleskli presne včas.“ Na záver si spolu povedzte: „Keď pozorne počúvam, veľa toho zachytím.“","tip":"Chváľte snahu a stratégiu, nie len výsledok."}]}'::jsonb, true),
('at-minuta-sustredenia-3', 'attention', 'guided', 'Minúta sústredenia', 'Udržiavaná pozornosť počas 60 sekúnd pri grafomotorickej úlohe s riadeným návratom k činnosti po distrakcii; metakognitívny cyklus plán → monitorovanie → reflexia podľa Mikulajovej.', 'Pripravte papier s bludiskom alebo veľkým tvarom, ceruzku a časovač. Pred štartom nechajte dieťa vybrať si stratégiu sústredenia a nahlas ju spolu zopakujte. Počas minúty seďte ticho a nezasahujte, ani keď dieťa spomalí. Po každom pokuse najprv oceňte snahu, až potom sa rozprávajte o tom, čo ho vyrušilo.', 3, 7, 10, 8, '{"type":"guided_steps","intro":"Jedna minúta, jedna úloha, žiadne vyrušenie — dokážeš to?","steps":[{"kicker":"Krok 1 · Príprava","title":"Pripravíme si všetko","body":"Pripravte papier s jednoduchým bludiskom alebo veľkým tvarom na obťahovanie (stačí nakresliť vlnovku či špirálu), ceruzku a časovač na 60 sekúnd. Povedzte dieťaťu: „Tvoja úloha je jediná — celú minútu ťahať čiaru a nenechať sa ničím vyrušiť.“ Potom sa opýtajte: „Ako sa cítiš pred takouto výzvou?“","choices":["Teším sa 😊","Cítim sa pokojne 😌","Trochu sa obávam 😕","Mám chuť to skúsiť 💪"],"tip":"Vyberte pokojné miesto bez televízora a mobilu. Každý pocit je v poriadku — len ho spolu pomenujte."},{"kicker":"Krok 2 · Plán","title":"Vyber si stratégiu","body":"Opýtajte sa: „Čo ti pomôže vydržať celú minútu?“ Nechajte dieťa vybrať si jednu alebo dve stratégie a nahlas ich zopakujte.","choices":["Pozerám len na papier 👀","Poviem si: pomaly a pokojne 🐢","Keď ma niečo vyruší, vrátim sa k čiare ↩️","Pokojne dýcham 🌬️"],"tip":"Stratégiu vyberá dieťa, nie vy. Vy mu ju len pomôžete pomenovať."},{"kicker":"Krok 3 · Prvý pokus","title":"Minúta sústredenia","body":"Spustite časovač na 60 sekúnd. Dieťa ťahá čiaru cez bludisko alebo obťahuje tvar. Vy sedíte ticho a len pozorujete.","tip":"Ani slovkom nepomáhajte — všímajte si, kedy pozornosť uletí a kedy sa sama vráti. Nikdy neriešte úlohu za dieťa.","fields":[{"label":"Vydržalo dieťa celých 60 sekúnd?","placeholder":"áno / nie — kedy prestalo"}]},{"kicker":"Krok 4 · Druhý pokus","title":"Minúta s malým vyrušením","body":"Zopakujte minútu na novom tvare, ale tentoraz počas nej raz potichu položte na stôl hrnček alebo si odkašlite. Úlohou dieťaťa je zostať pri svojej čiare. Pred štartom si spolu zopakujte vybranú stratégiu.","tip":"Vyrušenie má byť jemné — cieľom je zážitok úspechu, nie nachytanie dieťaťa.","fields":[{"label":"Ako dieťa zareagovalo na vyrušenie?","placeholder":"napr. pozrelo sa a vrátilo sa k čiare"}]},{"kicker":"Krok 5 · Reflexia","title":"Zhodnotíme minútu","body":"Opýtajte sa: „Čo ťa najviac ťahalo preč od úlohy? Ktorá stratégia ti pomohla?“ Odpovede dieťaťa zapíšte jeho vlastnými slovami.","tip":"Neponúkajte odpovede — počkajte, kým dieťa samo pomenuje, čo mu pomohlo.","fields":[{"label":"Čo dieťa najviac vyrušovalo?","placeholder":"napr. zvuky z vedľajšej izby"},{"label":"Ktorá stratégia mu pomohla?","placeholder":"napr. pozerať len na papier"}]},{"kicker":"Krok 6 · Ukotvenie","title":"Veta na záver","body":"Pochváľte konkrétne, napríklad: „Aj po vyrušení sa tvoja ceruzka vrátila k čiare — to je majstrovské sústredenie.“ Na záver si spolu povedzte: „Dokážem sa sústrediť krok za krokom.“","tip":"Oceňte návrat k úlohe po vyrušení — to je väčší úspech než minúta bez zaváhania."}]}'::jsonb, true),
('gu-zaseknuta-skladacka-2', 'guided', 'guided', 'Zaseknutá skladačka', 'Kľúčové metakognitívne cvičenie (podľa Mikulajovej): dieťa pri náročnej skladačke prechádza cyklom identifikácia emócie → plánovanie → monitorovanie → hodnotenie. Rozvíja exekutívne funkcie, frustračnú toleranciu a vnútornú reč pri riešení problému.', 'Pripravte na stôl skladačku s 10 – 20 dielikmi, ktorú dieťa ešte neskladalo. Sadnite si vedľa neho a povedzte: „Toto je hlavolam pre teba. Ja budem pri tebe, ale skladať budeš ty.“ Keď sa dieťa zasekne, nesiahajte na dieliky — pýtajte sa: „Čo by si mohol skúsiť ďalej?“, „Ktorý dielik má rovnú hranu?“ Ak rastie frustrácia, pokojne ju pomenujte: „Vidím, že ťa to hnevá. To je v poriadku, zaseknutie patrí k skladaniu.“ Premýšľajte nahlas len ako vzor, nikdy nie ako hotové riešenie.', 2, 6, 10, 12, '{"type":"guided_steps","intro":"Dnes ťa čaká hlavolam. Nie je ľahký — a práve preto je super! Zaseknúť sa nie je chyba: je to znamenie, že sa práve učíš.","steps":[{"kicker":"Krok 1 · Príprava","title":"Pripravte scénu","body":"Položte pred dieťa skladačku s 10 – 20 dielikmi, ktorú ešte neskladalo. Dieliky vysypte a pootáčajte obrázkom nahor. Povedzte: „Toto je úloha pre teba. Ja ti budem robiť spoločnosť, ale ruky do toho dám, len keď si to sám vypýtaš.“","tip":"Odolajte chuti ukázať prvý ťah. Nikdy neriešte úlohu za dieťa — vaša práca je pýtať sa, nie skladať."},{"kicker":"Krok 2 · Pocity","title":"Ako sa cítiš?","body":"Skôr než dieťa začne, spýtajte sa: „Pozri sa na tie dieliky. Ako sa pri nich cítiš?“ Nechajte dieťa vybrať pocit — pokojne aj viac naraz. Každý pocit je v poriadku.","choices":["Pokoj","Zmätok","Nervozita","Hnev","Zvedavosť","Odhodlanie"],"tip":"Pocit neopravujte ani nezľahčujte („netreba sa báť“). Len ho zopakujte: „Aha, cítiš zmätok. Ďakujem, že si mi to povedal.“"},{"kicker":"Krok 3 · Plán","title":"Urobme si plán","body":"Povedzte: „Skôr než začneš, chvíľku spolu porozmýšľame.“ Položte dieťaťu tri otázky a odpovede zapíšte jeho vlastnými slovami.","fields":[{"label":"Čo od teba úloha žiada?","placeholder":"napr. poskladať celý obrázok z dielikov"},{"label":"Čo už vieš?","placeholder":"napr. rohové dieliky majú dve rovné hrany"},{"label":"Aký je prvý malý krok?","placeholder":"napr. nájdem všetky dieliky s rovnou hranou"}],"tip":"Ak dieťa mlčí, nenapovedajte plán za neho. Len zúžte otázku: „Čo vidíš na obrázku na krabici?“"},{"kicker":"Krok 4 · Riešenie","title":"Teraz skladáš ty","body":"Dieťa pracuje samo podľa svojho plánu a vy sa držíte späť. Keď sa zasekne, nesiahajte na dieliky — navádzajte otázkami: „Čo by si mohol skúsiť ďalej?“, „Ktorá farba je na obrázku hore?“, „Pomohol by ti teraz tvoj plán?“ Priebežne si značte, čo dieťa skúšalo.","fields":[{"label":"Čo dieťa skúšalo?","placeholder":"napr. triedilo dieliky podľa farby, začalo od rohov"}],"tip":"Najťažší krok pre vás: mlčte a čakajte. Dobre položené ticho naučí viac než hotové riešenie — nikdy neskladajte za dieťa."},{"kicker":"Krok 5 · Reflexia","title":"Pozrime sa späť","body":"Po dokončení (alebo po dohodnutom čase) sa spolu pozrite na prácu. Spýtajte sa: „Čo sa ti darilo?“ a „Čo bolo ťažké?“ Odpovede dieťaťa zapíšte.","fields":[{"label":"Čo sa darilo?","placeholder":"napr. našiel všetky rohy sám"},{"label":"Čo bolo ťažké?","placeholder":"napr. dieliky oblohy vyzerali rovnako"}],"tip":"Aj nedokončená skladačka je úspech, ak dieťa skúšalo vlastné cesty. Hodnotíme cestu, nie obrázok."},{"kicker":"Krok 6 · Ukotvenie","title":"Veta pre mňa","body":"Povedzte: „Vyber si vetu, ktorá dnes platí o tebe, a povedz ju nahlas.“ Pokojne aj viackrát, ako zaklínadlo.","choices":["Zvládnem to krok za krokom.","Zaseknutie mi pomáha učiť sa.","Môžem to skúsiť inak."],"tip":"Vetu nevyberajte za dieťa. Ukotvenie posilní sebadôveru, len keď si ho dieťa zvolí samo."}]}'::jsonb, true),
('gu-citanie-spolu-2', 'guided', 'guided', 'Čítame spolu: pred, počas, po', 'Dialogické čítanie so stratégiami pred čítaním (predikcia z obálky), počas čítania (monitorovanie porozumenia, prepájanie s vlastnou skúsenosťou) a po čítaní (sumarizácia vlastnými slovami). Rozvíja čitateľské porozumenie, naratívne schopnosti a metakognitívnu kontrolu porozumenia.', 'Vyberte s dieťaťom krátku knižku alebo príbeh, ktorý ešte nepozná. Pred čítaním ukážte obálku a spýtajte sa: „O čom asi bude tento príbeh? Podľa čoho to vieš?“ Počas čítania sa dva-trikrát zastavte a pýtajte sa: „Čo myslíš, čo sa stane teraz?“ a „Stalo sa niečo podobné aj tebe?“ Po dočítaní poproste: „Porozprávaj mi príbeh vlastnými slovami — predstav si, že ho vôbec nepoznám.“ Ak sa dieťa zasekne, pomôžte otázkou „Ako sa to začalo?“, nie prerozprávaním.', 2, 6, 10, 12, '{"type":"guided_steps","intro":"Dnes budeme čítať ako detektívi: najprv budeme hádať, potom sa pýtať a nakoniec mi celý príbeh porozprávaš ty.","steps":[{"kicker":"Krok 1 · Príprava","title":"Vyberte knižku","body":"Nechajte dieťa vybrať krátku knižku alebo príbeh, ktorý ešte nepozná. Sadnite si vedľa seba tak, aby ste obaja videli na obrázky. Povedzte: „Dnes budeme čítať ako detektívi — budeme hádať, pýtať sa a skúmať.“","tip":"Počas celého čítania platí: otázky kladiete vy, odpovede patria dieťaťu. Nikdy neodpovedajte za neho."},{"kicker":"Krok 2 · Pocity","title":"Ako sa cítiš pred čítaním?","body":"Spýtajte sa: „Ako sa cítiš, keď držíš novú knižku?“ Nechajte dieťa vybrať pocit — aj viac naraz.","choices":["Zvedavosť","Radosť","Pokoj","Únava","Neistota"],"tip":"Aj únava či nechuť sú v poriadku. Pocit prijmite bez presviedčania — nerozprávajte dieťaťu, čo „má“ cítiť."},{"kicker":"Krok 3 · Pred čítaním","title":"Hádaj z obálky","body":"Prezrite si spolu obálku. Spýtajte sa: „O čom asi bude príbeh? Podľa čoho to vieš?“ Predpoveď zapíšte vlastnými slovami dieťaťa — na konci sa k nej vrátime.","fields":[{"label":"Čo dieťa predpovedalo?","placeholder":"napr. bude to o stratenom psíkovi, lebo na obálke je smutný pes"}],"tip":"Žiadna predpoveď nie je zlá. Neopravujte ju, ani keď dej poznáte — predpoveď patrí dieťaťu, nie vám."},{"kicker":"Krok 4 · Počas čítania","title":"Zastav sa a pýtaj sa","body":"Čítajte a na napínavých miestach sa dva-trikrát zastavte. Pýtajte sa: „Čo myslíš, čo sa stane teraz?“ a „Zažil si niečo podobné?“ Nechajte dieťa hovoriť, aj keby odbočilo od deja.","fields":[{"label":"Aké prepojenie na vlastnú skúsenosť dieťa našlo?","placeholder":"napr. aj ja som sa raz stratil v obchode"}],"tip":"Neodpovedajte na svoje otázky sami. Ticho po otázke je priestor pre dieťa, nie chyba."},{"kicker":"Krok 5 · Po čítaní","title":"Prerozprávaj vlastnými slovami","body":"Po dočítaní povedzte: „Porozprávaj mi príbeh vlastnými slovami — predstav si, že ho vôbec nepoznám.“ Toto je chvíľa dieťaťa — nechajte ho rozprávať bez prerušovania. Ak sa zasekne, pomôžte len otázkou: „Ako sa to začalo?“","fields":[{"label":"Ako dieťa zhrnulo príbeh?","placeholder":"napr. začiatok — problém — koniec vlastnými slovami"}],"tip":"Nedopĺňajte dej za dieťa. Jeho neúplné zhrnutie je cennejšie než vaše dokonalé."},{"kicker":"Krok 6 · Reflexia","title":"Sedela tvoja predpoveď?","body":"Vráťte sa k predpovedi z obálky. Spýtajte sa: „Uhádol si niečo? Čo ťa v príbehu prekvapilo?“ a „Čo ti dnes pomohlo príbehu rozumieť?“","fields":[{"label":"Čo sa z predpovede splnilo?","placeholder":"napr. psík sa naozaj stratil, ale koniec bol iný"},{"label":"Čo dieťa prekvapilo?","placeholder":"napr. že psíkovi pomohla mačka"}],"tip":"Nesplnená predpoveď nie je prehra — povedzte: „Detektív háda a potom overuje. Presne to si urobil.“"},{"kicker":"Krok 7 · Ukotvenie","title":"Veta pre mňa","body":"Povedzte: „Vyber si vetu, ktorá dnes platí o tebe, a povedz ju nahlas.“","choices":["Keď sa pýtam, príbehu rozumiem.","Moje predpovede mi pomáhajú čítať.","Viem prerozprávať príbeh vlastnými slovami."],"tip":"Vetu nechajte vybrať dieťa — ukotvenie funguje, len keď je jeho vlastné."}]}'::jsonb, true),
('gu-pocitova-mapa-1', 'guided', 'guided', 'Pocitová mapa dňa', 'Identifikácia a pomenúvanie emócií z priebehu dňa spolu s hľadaním funkčných regulačných stratégií. Buduje emočnú slovnú zásobu, sebauvedomovanie a základy sebaregulácie ako predpoklad metakognitívneho učenia.', 'Vyberte pokojnú chvíľu, napríklad večer pred spaním. Povedzte: „Poď, prejdeme si tvoj deň ako mapu so zastávkami.“ Dieťa si samo vyberie tri momenty dňa a pri každom sa spýtajte: „Aký pocit tam bol?“ Ak pocit nevie pomenovať, ponúknite dva na výber: „Bola to skôr radosť, alebo skôr hnev?“ Pri ťažkých pocitoch sa spýtajte: „A čo ti vtedy pomohlo?“ Pocity nikdy nezľahčujte („veď o nič nešlo“) — pre dieťa boli skutočné.', 1, 5, 8, 8, '{"type":"guided_steps","intro":"Tvoj deň je ako cesta so zastávkami. Poď, prejdeme si ju spolu a pri každej zastávke sa pozrieme, aké pocity tam boli.","steps":[{"kicker":"Krok 1 · Príprava","title":"Nájdite pokojnú chvíľu","body":"Sadnite si spolu bez obrazoviek — napríklad večer pred spaním. Môžete si vziať papier a nakresliť cestu so zastávkami. Povedzte: „Poď, pozrieme sa spolu na tvoj deň ako na mapu.“","tip":"Toto nie je výsluch, ale spoločná prechádzka. Nepredbiehajte dieťa vlastnými spomienkami na jeho deň."},{"kicker":"Krok 2 · Pocity","title":"Ako sa cítiš práve teraz?","body":"Začnite prítomnosťou: „Ako sa cítiš práve teraz, keď tu spolu sedíme?“ Nechajte dieťa vybrať — pokojne aj viac pocitov naraz.","choices":["Radosť","Pokoj","Smútok","Hnev","Strach","Únava"],"tip":"Každý pocit prijmite bez opravovania. Nehovorte dieťaťu, čo by „malo“ cítiť."},{"kicker":"Krok 3 · Plán","title":"Naplánuj si zastávky","body":"Povedzte: „Tvoj deň je ako cesta. Vyber si tri zastávky, o ktorých mi porozprávaš.“ Momenty dňa si volí dieťa samo — do výberu mu nevstupujte.","fields":[{"label":"Ktoré tri zastávky dňa si dieťa vybralo?","placeholder":"napr. raňajky, telocvik, cesta domov"}],"tip":"Nevyberajte zastávky za dieťa, ani keď viete o dôležitej udalosti. Príde na ňu, keď bude pripravené."},{"kicker":"Krok 4 · Rozprávanie","title":"Prejdi svoju mapu","body":"Dieťa pri každej zastávke samo rozpráva: čo sa tam dialo a ako sa cítilo. Vy len počúvate a prikyvujete. Pri ťažkom pocite sa spýtajte: „A čo ti vtedy pomohlo?“","fields":[{"label":"Čo dieťaťu pomohlo pri ťažkom pocite?","placeholder":"napr. objatie, hlboký nádych, kamarát"}],"tip":"Nenavrhujte riešenia za dieťa. Otázka „Čo ti pomohlo?“ hľadá jeho vlastné stratégie — tie si zapamätá najlepšie."},{"kicker":"Krok 5 · Reflexia","title":"Pozri sa na celú mapu","body":"Pozrite sa spolu na celý deň. Spýtajte sa: „Ktorý pocit bol dnes najväčší?“ a „Bolo ľahké o pocitoch rozprávať?“","fields":[{"label":"Ktorý pocit bol dnes najväčší?","placeholder":"napr. radosť z telocviku"},{"label":"Čo bolo ľahké a čo ťažké pomenovať?","placeholder":"napr. hnev sa hľadal ťažko"}],"tip":"Oceňte samotné rozprávanie, nie „pekné“ pocity: „Ďakujem, že si mi o tom povedal.“"},{"kicker":"Krok 6 · Ukotvenie","title":"Veta pre mňa","body":"Povedzte: „Vyber si vetu, ktorá dnes platí o tebe, a povedz ju nahlas.“","choices":["Svoje pocity smiem povedať nahlas.","Každý pocit raz prejde.","Viem, čo mi pomáha."],"tip":"Nechajte vetu vybrať dieťa. Vaša úloha je len svedok — nie sudca ani poradca."}]}'::jsonb, true),
('gu-chyba-je-kamarat-2', 'guided', 'guided', 'Chyba je kamarát', 'Kognitívne prerámcovanie chyby: dieťa analyzuje vlastnú nedávnu chybu, extrahuje z nej poučenie a preformuluje ju na skúsenosť. Podporuje rastové nastavenie mysle, frustračnú toleranciu a sebahodnotenie oddelené od sebaobviňovania.', 'Začnite vlastnou drobnou chybou z posledných dní a povedzte aj to, čo vás naučila. Potom nechajte dieťa vybrať si jeho chybu. Skúmajte ju spolu ako detektívi tromi otázkami: Čo sa stalo? Prečo sa to mohlo stať? Čo mi to prezradilo? Na záver pomôžte dieťaťu chybu preformulovať: „Pomýlil som sa v… a naučilo ma to…“ Ak dieťa povie „som hlúpy“, jemne vráťte reč k činu: „Nepodarila sa úloha. Ty si v poriadku.“', 2, 6, 10, 10, '{"type":"guided_steps","intro":"Chyba môže byť kamarát — dnes jednu spolu preskúmame ako detektívi a zistíme, čo ťa naučila.","steps":[{"kicker":"Krok 1 · Príprava","title":"Začnite vlastnou chybou","body":"Povedzte: „Dnes sa budeme rozprávať o chybách. Začnem ja.“ Podeľte sa o svoju drobnú nedávnu chybu a o to, čo vás naučila. Ukážete tak, že o chybách sa dá hovoriť bezpečne.","tip":"Vyberte naozaj drobnú vlastnú chybu a hovorte o nej ľahko, s úsmevom. Nevyberajte však chybu za dieťa — jeho výber príde v ďalšom kroku."},{"kicker":"Krok 2 · Pocity","title":"Ako sa pri spomienke cítiš?","body":"Povedzte: „Spomeň si na jednu svoju nedávnu chybu alebo na niečo, čo sa ti nepodarilo. Ako sa pri tej spomienke cítiš?“","choices":["Hanba","Smútok","Hnev","Neistota","Pokoj","Pobavenie"],"tip":"Prijmite každý pocit bez opravovania. Veta „netreba sa hanbiť“ pocit nezruší, len ho umlčí."},{"kicker":"Krok 3 · Plán","title":"Plán detektíva","body":"Povedzte: „Budeme detektívi a tvoju chybu preskúmame. Detektív sa pýta: Čo sa stalo? Prečo sa to mohlo stať? Čo mi to prezradilo?“ Zapíšte, ktorú chybu si dieťa vybralo.","fields":[{"label":"Akú chybu si dieťa vybralo?","placeholder":"napr. zabudol som si úbor na telocvik"}],"tip":"Chybu nevyberajte za dieťa a nezľahčujte ju („to nič nebolo“). Pre dieťa je skutočná."},{"kicker":"Krok 4 · Skúmanie","title":"Detektív pracuje sám","body":"Dieťa samo odpovedá na tri detektívne otázky a vy len zapisujete jeho slová. Ak sa zasekne, zopakujte otázku pomalšie alebo sa spýtajte: „Čo by si poradil kamarátovi, keby sa mu to stalo?“","fields":[{"label":"Čo sa dieťa z chyby naučilo?","placeholder":"napr. večer si nachystám veci podľa rozvrhu"}],"tip":"Neponúkajte vlastné ponaučenie a neriešte skúmanie za dieťa. Objav má hodnotu, len keď ho urobí samo."},{"kicker":"Krok 5 · Reflexia","title":"Povedz to novou vetou","body":"Pomôžte dieťaťu zložiť novú vetu: „Pomýlil som sa v… a naučilo ma to…“ Nechajte ho vetu povedať nahlas. Potom sa spýtajte: „Čo bolo na dnešnom skúmaní ťažké?“","fields":[{"label":"Ako znie nová veta dieťaťa?","placeholder":"napr. zabudol som úbor a naučilo ma to chystať si veci večer"},{"label":"Čo bolo pri skúmaní ťažké?","placeholder":"napr. hovoriť o hanbe"}],"tip":"Novú vetu skladá dieťa, vy len držíte jej začiatok. Nedokončujte ju za neho."},{"kicker":"Krok 6 · Ukotvenie","title":"Veta pre mňa","body":"Povedzte: „Vyber si vetu, ktorá dnes platí o tebe, a povedz ju nahlas.“","choices":["Chyby ma učia.","Pomýliť sa je ľudské.","Nabudúce to skúsim inak."],"tip":"Vetu si volí dieťa samo — práve tým sa ukotvuje jeho sebadôvera, nie vaša pochvala."}]}'::jsonb, true),
('gu-stavanie-podla-planu-1', 'guided', 'guided', 'Staviame podľa plánu', 'Prechod od konkrétnej manipulácie k symbolickej reprezentácii: dieťa najprv vytvorí grafický plán stavby a následne ho realizuje z kociek. Rozvíja plánovanie, vizuálno-priestorové funkcie a porovnávanie zámeru s výsledkom (monitorovanie a hodnotenie).', 'Pripravte kocky alebo stavebnicu, papier a ceruzku. Povedzte: „Stavitelia si najprv kreslia plán. Nakresli mi, čo postavíš.“ Prijmite akýkoľvek nákres — aj tri čiarky sú plán. Počas stavania sa nedotýkajte kociek. Keď sa dieťa zasekne, pýtajte sa: „Pozri do plánu — čo tam máš nakreslené?“ Na konci položte stavbu vedľa nákresu a porovnajte ich spolu: „Čo sedí? Čo je inak?“ Rozdiel medzi plánom a stavbou nie je chyba — je to objav.', 1, 5, 8, 10, '{"type":"guided_steps","intro":"Dnes budeš staviteľ! Najprv si nakreslíš plán a potom podľa neho postavíš vlastnú stavbu.","steps":[{"kicker":"Krok 1 · Príprava","title":"Pripravte stavenisko","body":"Položte na stôl kocky alebo stavebnicu, papier a ceruzku. Povedzte: „Dnes budeš staviteľ. A správny staviteľ si najprv nakreslí plán.“","tip":"Pripravte len materiál. Čo a ako sa postaví, je odteraz v rukách dieťaťa — nestavajte za neho ani kúsok."},{"kicker":"Krok 2 · Pocity","title":"Ako sa cíti staviteľ?","body":"Spýtajte sa: „Ako sa cítiš, keď máš byť staviteľom?“ Nechajte dieťa vybrať pocit.","choices":["Radosť","Zvedavosť","Neistota","Odhodlanie"],"tip":"Pocit len prijmite a zopakujte. Neistota pred novou úlohou je úplne v poriadku."},{"kicker":"Krok 3 · Plán","title":"Nakresli plán","body":"Dieťa nakreslí jednoduchý plán stavby — stačí pár čiar. Pýtajte sa: „Čo postavíš? Koľko kociek asi budeš potrebovať?“ Zapíšte, čo si dieťa naplánovalo.","fields":[{"label":"Čo chce dieťa postaviť?","placeholder":"napr. vežu pre draka, most, garáž"}],"tip":"Nekreslite plán za dieťa a neopravujte ho. Krivý nákres je stále plán."},{"kicker":"Krok 4 · Stavanie","title":"Teraz stavia staviteľ","body":"Dieťa stavia samo podľa vlastného nákresu a vy sa kociek nedotýkate. Keď sa zasekne, pýtajte sa: „Pozri do plánu — čo tam máš nakreslené?“ alebo „Čo by si mohol skúsiť inak?“","tip":"Najťažšia časť pre rodiča: ruky za chrbtom. Padnutá veža naučí viac než veža postavená vami."},{"kicker":"Krok 5 · Reflexia","title":"Sedí stavba s plánom?","body":"Položte hotovú stavbu vedľa nákresu. Spýtajte sa: „Sedí stavba s plánom? Čo je rovnaké a čo je inak?“","fields":[{"label":"Sedela stavba s plánom? Čo bolo inak?","placeholder":"napr. veža je nižšia, lebo kocky padali"},{"label":"Čo by dieťa nabudúce nakreslilo inak?","placeholder":"napr. širší základ veže"}],"tip":"Rozdiely nekomentujte ako chyby. Otázka „Čo je inak?“ je objavovanie, nie známkovanie."},{"kicker":"Krok 6 · Ukotvenie","title":"Veta pre mňa","body":"Povedzte: „Vyber si vetu, ktorá dnes platí o tebe, a povedz ju nahlas.“","choices":["Najprv rozmýšľam, potom staviam.","Môj plán mi pomáha.","Keď plán nesedí, môžem ho zmeniť."],"tip":"Vetu si vyberá dieťa samo — tak sa plánovanie prepojí s jeho sebadôverou."}]}'::jsonb, true),
('gu-spolocna-hra-1', 'guided', 'guided', 'Spoločná hra: vyhrávam aj prehrávam', 'Spoločenská hra ako tréning emočnej regulácie: dieťa si vopred pripraví stratégiu zvládania prehry a po hre reflektuje emócie z výhry i prehry. Posilňuje frustračnú toleranciu, sebareguláciu a rešpektovanie pravidiel.', 'Vyberte krátku spoločenskú hru, v ktorej rozhoduje aj šťastie, aby mohol vyhrať ktokoľvek — napríklad kartovú alebo kockovú. Pred hrou sa spýtajte: „Čo urobíš, keď budeš prehrávať?“ a plán spolu nahlas zopakujte. Hrajte naozaj — nenechávajte dieťa zámerne vyhrať zakaždým. Keď príde ťažká chvíľa, nepreberajte riadenie: pokojne pripomeňte otázkou „Aký bol tvoj plán?“ Po hre sa rozprávajte o pocitoch z výhry aj prehry a oceňte, keď dieťa svoj plán použilo.', 1, 5, 9, 12, '{"type":"guided_steps","intro":"Zahráme si spolu hru! Niekedy sa vyhráva, niekedy prehráva — a ty budeš mať pripravený svoj tajný plán.","steps":[{"kicker":"Krok 1 · Príprava","title":"Vyberte hru","body":"Nechajte dieťa vybrať krátku hru, v ktorej rozhoduje aj šťastie — napríklad kartovú alebo kockovú. Povedzte: „Zahráme si naozaj. Niekedy vyhráš ty, niekedy ja — a oboje patrí k hre.“","tip":"Nenechávajte dieťa zámerne vyhrávať zakaždým. Bezpečná skúsenosť s prehrou pri vás je cieľom cvičenia."},{"kicker":"Krok 2 · Pocity","title":"Ako sa cítiš pred hrou?","body":"Spýtajte sa: „Ako sa cítiš, keď vieš, že budeme súperiť?“ Nechajte dieťa vybrať pocit.","choices":["Radosť","Napätie","Zvedavosť","Obava","Pokoj"],"tip":"Aj napätie a obava sú v poriadku. Pomenovaný pocit sa počas hry zvláda ľahšie."},{"kicker":"Krok 3 · Plán","title":"Čo urobím, keď budem prehrávať?","body":"Spýtajte sa: „Čo urobíš, keď budeš prehrávať?“ Dieťa si vymyslí malý plán — napríklad urobiť hlboký nádych, napiť sa vody alebo si povedať „je to len hra“. Spýtajte sa aj: „A čo urobíš, keď vyhráš?“","fields":[{"label":"Plán dieťaťa na prehrávanie","placeholder":"napr. tri hlboké nádychy a hrám ďalej"},{"label":"Plán dieťaťa na výhru","placeholder":"napr. poviem súperovi „dobrá hra“"}],"tip":"Plán nevymýšľajte za dieťa. Príklad ponúknite, len keď si samo nevie poradiť — a nechajte ho vybrať."},{"kicker":"Krok 4 · Hra","title":"Hráme naozaj","body":"Hrajte podľa pravidiel. Keď dieťa začne prehrávať a rastú emócie, nezasahujte do jeho prežívania — len pokojne pripomeňte otázkou: „Aký bol tvoj plán?“","tip":"Nezachraňujte dieťa pred prehrou úpravou pravidiel a neriešte ťažkú chvíľu za neho. Zvládnutá emócia je väčšia výhra než bod v hre."},{"kicker":"Krok 5 · Reflexia","title":"Ako ti bolo pri hre?","body":"Po hre sa spýtajte: „Ako ti bolo, keď si vyhrával? A keď si prehrával? Pomohol ti tvoj plán?“ Odpovede zapíšte.","fields":[{"label":"Ako dieťa opísalo pocity z výhry a prehry?","placeholder":"napr. pri prehre hnev, potom to prešlo"},{"label":"Použilo dieťa svoj plán? Čo pomohlo?","placeholder":"napr. nádychy pomohli, chcelo hrať odvetu"}],"tip":"Oceňte použitie plánu, nie výsledok hry: „Páčilo sa mi, ako si sa nadýchol a hral ďalej. To bolo silné.“"},{"kicker":"Krok 6 · Ukotvenie","title":"Veta pre mňa","body":"Povedzte: „Vyber si vetu, ktorá dnes platí o tebe, a povedz ju nahlas.“","choices":["Prehra nie je koniec sveta.","Hrám pre radosť z hry.","Mám plán a viem ho použiť."],"tip":"Vetu si volí dieťa samo. Ak žiadna nesedí, nechajte ho vymyslieť vlastnú."}]}'::jsonb, true),
('gu-planovanie-ulohy-3', 'guided', 'guided', 'Môj vlastný plán', 'Samostatné plánovanie viackrokovej činnosti (kroky, odhad času, pomôcky) s rodičom v role zapisovateľa a následné porovnanie plánu so skutočnosťou. Rozvíja exekutívne funkcie — plánovanie, odhad času, monitorovanie a hodnotenie — pri minimálnej opore dospelého.', 'Vyberte s dieťaťom skutočnú väčšiu činnosť — domácu úlohu, upratanie izby alebo prípravu desiatej. Vaša rola je zapisovateľ: povedzte „Ty si šéf plánu, ja len píšem.“ Zapisujte kroky presne tak, ako ich dieťa diktuje, aj keď vidíte medzeru. Ak je plán deravý, spýtajte sa nanajvýš: „Netreba ti k tomu ešte niečo?“ Počas práce mlčte; na požiadanie plán prečítajte. Po dokončení porovnajte plán so skutočnosťou bez hodnotenia — rozdiely sú materiál na učenie, nie chyby.', 3, 8, 10, 12, '{"type":"guided_steps","intro":"Dnes si šéfom ty! Naplánuješ si kroky, čas aj pomôcky — a ja budem len zapisovať.","steps":[{"kicker":"Krok 1 · Príprava","title":"Vyberte činnosť a role","body":"Vyberte spolu skutočnú činnosť — domácu úlohu, upratanie izby či prípravu desiatej. Povedzte: „Dnes plánuješ ty. Ja som len tvoj zapisovateľ.“ Vezmite si papier a pero.","tip":"Naozaj len zapisujte. Ani jeden krok plánu nesmie byť váš — neplánujte za dieťa."},{"kicker":"Krok 2 · Pocity","title":"Ako sa cíti šéf plánu?","body":"Spýtajte sa: „Ako sa cítiš, keď máš byť šéfom celého plánu?“ Nechajte dieťa vybrať pocit.","choices":["Odhodlanie","Pokoj","Nechuť","Nervozita","Zvedavosť"],"tip":"Aj nechuť je informácia, nie problém. Prijmite ju: „Rozumiem, veľká úloha. Uvidíme, čo s ňou plán urobí.“"},{"kicker":"Krok 3 · Plán krokov","title":"Diktuj mi kroky","body":"Dieťa diktuje kroky a vy ich číslujete a zapisujete jeho slovami. Ak vidíte medzeru, nedopĺňajte ju — nanajvýš sa spýtajte: „Netreba ti k tomu ešte niečo?“","fields":[{"label":"Aké kroky si dieťa naplánovalo?","placeholder":"napr. 1. nachystám si zošit, 2. prečítam zadanie…"}],"tip":"Deravý plán nechajte deravý. Dieťa sa z medzery naučí viac než z vášho doplnenia."},{"kicker":"Krok 4 · Čas a pomôcky","title":"Koľko času? Čo budeš potrebovať?","body":"Spýtajte sa: „Koľko času ti to asi zaberie?“ a „Čo všetko budeš potrebovať?“ Odhady zapíšte — po skončení sa k nim vrátite.","fields":[{"label":"Odhad času dieťaťa","placeholder":"napr. 20 minút"},{"label":"Naplánované pomôcky","placeholder":"napr. zošit, pero, pravítko"}],"tip":"Nereálny odhad neopravujte. Porovnanie so skutočnosťou ho opraví lepšie než vy."},{"kicker":"Krok 5 · Realizácia","title":"Šéf pracuje, zapisovateľ mlčí","body":"Dieťa pracuje podľa svojho plánu. Vy nezasahujete — na požiadanie iba prečítate plán. Ak dieťa od plánu odbočí, nekomentujte to; všimnete si to spolu pri porovnaní.","tip":"Mlčať pri odbočke od plánu je súčasť metódy. Porovnanie na konci povie viac než napomenutie uprostred — nerobte prácu za dieťa."},{"kicker":"Krok 6 · Porovnanie","title":"Plán verzus skutočnosť","body":"Po dokončení si spolu prečítajte plán. Pýtajte sa: „Čo išlo presne podľa plánu? Čo trvalo dlhšie? Čo ti chýbalo, hoci to v pláne nebolo?“","fields":[{"label":"Čo išlo podľa plánu?","placeholder":"napr. kroky sedeli, poradie fungovalo"},{"label":"Čo bolo v skutočnosti inak (čas, kroky, pomôcky)?","placeholder":"napr. trvalo to 35 minút, chýbala guma"}],"tip":"Rozdiely čítajte zvedavo, nie vyčítavo: „Zaujímavé, tu sa plán a skutočnosť rozišli. Čo myslíš, prečo?“"},{"kicker":"Krok 7 · Ukotvenie","title":"Veta pre mňa","body":"Povedzte: „Vyber si vetu, ktorá dnes platí o tebe, a povedz ju nahlas.“","choices":["Dobrý plán mi šetrí sily.","Viem si prácu rozdeliť na kroky.","Odhadovať čas sa učím tréningom."],"tip":"Vetu si vyberá dieťa samo — šéfom plánu zostáva až do poslednej vety."}]}'::jsonb, true),
('na-usporiadaj-pribeh-1', 'narrative', 'interactive', 'Poskladaj príbeh', 'Usporadúvanie trojkartových dejových sekvencií s následným prerozprávaním rozvíja chápanie časovej postupnosti a základnej makroštruktúry naratívu (začiatok – priebeh – koniec).', 'Prečítajte dieťaťu názov príbehu a spolu si pomenujte, čo je na jednotlivých kartách. Spýtajte sa: „Čo sa muselo stať najprv?“ Kartu nechajte vybrať dieťa. Ak váha, ukážte na dve karty a spýtajte sa, ktorá z nich bola skôr. Po usporiadaní nechajte dieťa príbeh porozprávať vlastnými slovami a pomáhajte len otázkami: Čo bolo potom? Ako sa to skončilo?', 1, 5, 7, 6, '{"type":"story_sequence","intro":"Karty sa pomiešali! Ulož ich tak, ako sa príbeh naozaj stal, a potom mi ho porozprávaj.","items":[{"title":"Dobré ráno, Ema!","cards":[{"emoji":"😴","label":"Ema spí"},{"emoji":"⏰","label":"Zazvoní budík"},{"emoji":"🥣","label":"Ema raňajkuje"}],"retellPrompt":"Porozprávaj mi Emino ráno vlastnými slovami. Čo bolo najprv, čo potom a čo nakoniec?","hint":"Čo robí Ema, kým ešte budík nezazvoní?"},{"title":"Snehuliak","cards":[{"emoji":"❄️","label":"Vonku sneží"},{"emoji":"⛄","label":"Deti postavia snehuliaka"},{"emoji":"🥕","label":"Dajú mu nos z mrkvy"}],"retellPrompt":"Porozprávaj, ako deti stavali snehuliaka. Čím sa to celé začalo?","hint":"Môžu deti stavať snehuliaka skôr, ako nasneží?"},{"title":"Slnečnica","cards":[{"emoji":"🌱","label":"Zasadíme semienko"},{"emoji":"💧","label":"Polievame ho"},{"emoji":"🌻","label":"Vyrastie slnečnica"}],"retellPrompt":"Porozprávaj mi, ako zo semienka vyrástla veľká slnečnica.","hint":"Čo potrebuje semienko, aby mohlo rásť?"}]}'::jsonb, true),
('na-usporiadaj-pribeh-2', 'narrative', 'interactive', 'Poskladaj dlhší príbeh', 'Štvorkartové dejové sekvencie s dôrazom na temporálne konektory (najprv, potom, nakoniec) posilňujú kohéziu naratívu a plánovanie deja.', 'Prečítajte názov príbehu a spolu pomenujte všetky štyri karty. Spýtajte sa: „Čím sa to celé začalo?“ Dieťa ukladá karty samo; ak si nie je isté, porovnajte dve karty otázkou, ktorá z nich bola skôr. Pri prerozprávaní veďte dieťa k slovám najprv, potom a nakoniec — povedzte prvé slovo a nechajte ho vetu dokončiť.', 2, 6, 8, 7, '{"type":"story_sequence","intro":"Tieto príbehy majú štyri karty. Ulož ich pekne po poriadku a potom mi ich porozprávaj.","items":[{"title":"Narodeninová torta","cards":[{"emoji":"🥚","label":"Prichystáme vajcia a múku"},{"emoji":"🥣","label":"Zamiešame cesto"},{"emoji":"🎂","label":"Torta sa upečie"},{"emoji":"🎉","label":"Oslávime narodeniny"}],"retellPrompt":"Porozprávaj, ako vznikla narodeninová torta — od surovín až po oslavu.","hint":"Dá sa miešať cesto, keď ešte nemáme suroviny?"},{"title":"Dážď a dúha","cards":[{"emoji":"☁️","label":"Na oblohe sa objavia tmavé mraky"},{"emoji":"🌧️","label":"Spustí sa dážď"},{"emoji":"☀️","label":"Vykukne slnko"},{"emoji":"🌈","label":"Zažiari dúha"}],"retellPrompt":"Porozprávaj, čo sa dialo na oblohe. Skús použiť slová najprv, potom a nakoniec.","hint":"Kedy vidíme dúhu — pred dažďom, alebo po ňom?"},{"title":"Zablatený psík","cards":[{"emoji":"🐕","label":"Psík sa vyváľa v blate"},{"emoji":"🛁","label":"Dáme ho do vane"},{"emoji":"🧴","label":"Umyjeme ho šampónom"},{"emoji":"✨","label":"Psík je zase čistučký"}],"retellPrompt":"Porozprávaj psíkov príbeh. Prečo sa musel kúpať a ako to dopadlo?","hint":"Čo sa muselo stať, aby psík potreboval kúpeľ?"}]}'::jsonb, true),
('na-usporiadaj-pribeh-3', 'narrative', 'interactive', 'Prečo sa to stalo?', 'Päť- až šesťkartové sekvencie s príčinno-následkovými vzťahmi rozvíjajú kauzálne usudzovanie a produkciu komplexného naratívu s kauzálnymi konektormi (pretože, preto, a tak).', 'Nechajte dieťa najprv v tichosti prezrieť všetky karty. Spýtajte sa: „O čom asi ten príbeh bude?“ Pri ukladaní sa pýtajte na príčiny: „Prečo sa to stalo? Čo sa muselo stať predtým?“ Pri prerozprávaní oceňte, keď dieťa použije slová pretože, preto alebo a tak — sú znakom, že dej naozaj pochopilo.', 3, 7, 10, 8, '{"type":"story_sequence","intro":"Toto sú dlhšie príbehy. Ulož karty po poriadku a rozmýšľaj, prečo sa veci stali práve takto.","items":[{"title":"Mačiatko na strome","cards":[{"emoji":"🐱","label":"Mačiatko vybehne z domu"},{"emoji":"🌳","label":"Vylezie vysoko na strom"},{"emoji":"😿","label":"Bojí sa zliezť a smutne mňauká"},{"emoji":"👧","label":"Zuzka ho začuje a beží po pomoc"},{"emoji":"🧑‍🚒","label":"Hasič mačiatko opatrne znesie"},{"emoji":"🏡","label":"Mačiatko je doma v bezpečí"}],"retellPrompt":"Porozprávaj celý príbeh o mačiatku. Skús povedať aj to, prečo sa bálo a kto mu pomohol.","hint":"Prečo mačiatko mňaukalo? Čo sa stalo tesne predtým?"},{"title":"Tomáš a bicykel","cards":[{"emoji":"🚲","label":"Tomáš sa učí jazdiť na bicykli"},{"emoji":"🪨","label":"Nevšimne si kameň na ceste"},{"emoji":"🤕","label":"Spadne a odrie si koleno"},{"emoji":"🩹","label":"Mama mu koleno ošetrí"},{"emoji":"💪","label":"Skúsi to znova a podarí sa mu to"}],"retellPrompt":"Porozprávaj Tomášov príbeh. Prečo spadol a ako sa to celé skončilo?","hint":"Prečo Tomáš spadol? Čo ležalo na ceste?"}]}'::jsonb, true),
('na-rozpravaj-obrazok-1', 'narrative', 'speech', 'Rozprávaj o obrázku', 'Tvorba jednoduchých rozvitých viet k obrazovému podnetu. Cieľom je stabilná štruktúra podmet – prísudok a rozširovanie výpovede otázkami kto – čo robí – kde.', 'Ukážte dieťaťu obrázok a spýtajte sa: „Čo sa tu deje?“ Ak odpovie jedným slovom, položte tri pomocné otázky: Kto to je? Čo robí? Kde je? Potom celú vetu spoločne nahlas zopakujte. Chváľte každú celú vetu — presnosť je dôležitejšia než rýchlosť.', 1, 5, 7, 5, '{"type":"speech_items","intro":"Pozri sa na obrázky a povedz celou vetou, čo sa deje.","items":[{"text":"Povedz celou vetou, čo sa deje: 🐱🌳","emoji":"🐱🌳","tip":"Ak dieťa povie len jedno slovo, pýtajte sa: Kto to je? Čo robí? Kde je? Vzorová veta: „Mačka vyliezla na strom.“"},{"text":"Povedz celou vetou, čo sa deje: 👦⚽","emoji":"👦⚽","tip":"Pomôžte otázkami: Kto je na obrázku? Čo robí? S čím sa hrá?"},{"text":"Povedz celou vetou, čo sa deje: 🐶🦴","emoji":"🐶🦴","tip":"Ak vznikne len krátka veta, poproste dieťa, nech pridá, kde sa to deje alebo aká je kosť."},{"text":"Povedz celou vetou, čo sa deje: 👧📖","emoji":"👧📖","tip":"Rozšírte vetu otázkami: Kde dievčatko číta? O čom asi tá kniha je?"},{"text":"Povedz celou vetou, čo sa deje: 🐰🥕","emoji":"🐰🥕","tip":"Opýtajte sa: Kto to je? Čo chrúme? Ako mu asi chutí?"},{"text":"Povedz celou vetou, čo sa deje: 🐟🌊","emoji":"🐟🌊","tip":"Skúste vetu spoločne predĺžiť: Kde rybka pláva? Pláva rýchlo, či pomaly?"}]}'::jsonb, true),
('na-dokonci-pribeh-2', 'narrative', 'speech', 'Dokonči príbeh', 'Generovanie pokračovania a záveru príbehu rozvíja epizodickú štruktúru naratívu (zápletka – riešenie – záver), naratívnu fluenciu a divergentné myslenie.', 'Prečítajte začiatok príbehu pomaly a trochu tajomne. Potom sa spýtajte: „Čo sa stalo potom?“ Keď dieťa dorozpráva, pridajte druhú otázku: „A ako to celé dopadlo?“ Ak sa dieťa zasekne, ponúknite dve možnosti na výber, ale rozhodnutie nechajte vždy na ňom.', 2, 6, 9, 8, '{"type":"speech_items","intro":"Vypočuj si začiatok príbehu a vymysli, ako pokračuje a ako sa skončí.","items":[{"text":"Maja našla v tráve malé mačiatko. Bolo celkom samo a tíško mňaukalo…","emoji":"🐱","tip":"Navádzajte štruktúrou: Čo urobila Maja potom? A ako to nakoniec dopadlo?"},{"text":"Kubo staval z kociek vysokánsku vežu. Vtom do izby vbehol jeho malý braček…","emoji":"🧱","tip":"Ak dieťa skončí jednou vetou, spýtajte sa: Čo sa stalo potom? Ako sa cítil Kubo?"},{"text":"Hanka na výlete zbadala, že sa pod starým stromom niečo ligoce…","emoji":"✨","tip":"Podporte fantáziu: Čo to mohlo byť? Čo s tým Hanka urobila? Ako sa príbeh skončil?"},{"text":"Psík Dunčo vyhrabal na dvore starú škatuľku…","emoji":"🐶","tip":"Pýtajte sa: Čo bolo vnútri? Komu to Dunčo ukázal? Ako to dopadlo?"},{"text":"Lienka Bodka sa ráno zobudila a zistila, že jej chýba jedna bodka…","emoji":"🐞","tip":"Ak sa dieťa zasekne, ponúknite otázku: Kde ju mohla stratiť? Kto jej pomohol hľadať?"},{"text":"Do triedy prišiel nový chlapec. Nikoho nepoznal a hanbil sa…","emoji":"🏫","tip":"Zamerajte sa na záver: Kto sa s ním skamarátil? Ako sa cítil na konci dňa?"}]}'::jsonb, true),
('na-tajna-rec-rozpravok-2', 'narrative', 'guided', 'Tajná reč rozprávok', 'Symbolické modelovanie deja podľa metodiky Ďjačenkovej: dieťa externalizuje makroštruktúru známej rozprávky pomocou zástupných predmetov a prerozpráva ju s vizuálnou oporou — rozvoj sukcesívneho radenia deja a samostatnej naratívnej produkcie.', 'Prichystajte misku drobných predmetov (gombíky, kocky, viečka, kamienky) a vyberte rozprávku, ktorú dieťa dobre pozná. Prvýkrát rozprávate vy a dieťa ukladá predmety-postavy do radu. Potom si úlohy vymeníte: dieťa rozpráva, vy počúvate. Do rozprávania nevstupujte — ak sa dieťa stratí, iba ticho ukážte na ďalší predmet v rade.', 2, 6, 9, 12, '{"type":"guided_steps","intro":"Dnes budeme rozprávať rozprávku tajnou rečou — každú postavu zahrá malý predmet.","steps":[{"kicker":"Krok 1 · Naladenie","title":"Ako sa cítiš pred rozprávkou?","body":"Povedzte: „Chystá sa rozprávková hra! Ale najprv mi povedz, ako sa práve teraz cítiš.“ Nechajte dieťa vybrať a pocit spolu pomenujte.","choices":["Veselo","Zvedavo","Pokojne","Unavene"]},{"kicker":"Krok 2 · Plán","title":"Vyberte si rozprávku","body":"Povedzte: „Zahráme sa na tajnú reč rozprávok. Postavy nebudú na obrázkoch — zahrajú ich drobné predmety zo stola.“ Spolu si vyberte rozprávku, ktorú dieťa dobre pozná, a vymenujte jej postavy.","choices":["O repke","O troch prasiatkach","Červená čiapočka","O medovníkovom domčeku"],"tip":"Vyberte rozprávku, ktorú dieťa počulo veľakrát. Cieľom nie je učiť nový dej, ale rozprávať."},{"kicker":"Krok 3 · Príprava","title":"Tajné symboly postáv","body":"Nachystajte kôpku drobných predmetov: gombíky, kocky, viečka, kamienky, lyžičku. Za každú postavu nech si dieťa vyberie jeden predmet a povie, prečo sa hodí: „Myška bude tento malý gombík, lebo je maličká.“","fields":[{"label":"Kto koho hrá?","placeholder":"napr. veľká kocka = dedko, malý gombík = myška"}],"tip":"Nevyberajte predmety za dieťa. Každý výber je správny, ak ho dieťa vie zdôvodniť."},{"kicker":"Krok 4 · Dej","title":"Poskladajte dej z predmetov","body":"Pomaly rozprávajte rozprávku. Dieťa pri každej postave položí jej predmet do radu presne v poradí, v akom postavy vstupujú do deja. Na konci sa na rad spolu pozrite a povedzte: „Toto je celá naša rozprávka.“"},{"kicker":"Krok 5 · Samostatný pokus","title":"Dieťa rozpráva samo","body":"Teraz je rozprávačom dieťa. Prstom prechádza po rade predmetov a rozpráva rozprávku od začiatku do konca vlastnými slovami.","tip":"Nevstupujte do rozprávania a neopravujte. Ak sa dieťa zasekne, iba ticho ukážte na ďalší predmet v rade."},{"kicker":"Krok 6 · Reflexia","title":"Ako sa nám darilo?","body":"Spolu sa porozprávajte, ako sa dieťaťu rozprávalo. Spýtajte sa: „Čo ti išlo najľahšie? Kde ti pomohli predmety?“ Dieťa nech si vyberie, čo naň sedí.","choices":["Išlo mi to ľahko","Miestami to bolo ťažké","Pomohli mi predmety v rade"],"fields":[{"label":"Čo sa dieťaťu darilo najviac?","placeholder":"napr. vymenovalo všetky postavy v správnom poradí"},{"label":"Kde potrebovalo pomoc?","placeholder":"napr. pripomenúť, kto prišiel na rad po psíkovi"}]},{"kicker":"Krok 7 · Ukotvenie","title":"Zvládnem to krok za krokom","body":"Pomenujte úspech konkrétne: dieťa porozprávalo celú rozprávku samo a predmety mu pomohli udržať poradie. Spolu nahlas zopakujte: „Rozprávku zvládnem krok za krokom.“"}]}'::jsonb, true),
('na-moj-den-1', 'narrative', 'guided', 'Môj deň', 'Personálny naratív so štruktúrovanou časovou osnovou (ráno – doobeda – poobede – večer) rozvíja autobiografické rozprávanie, sekvenčné radenie udalostí a epizodickú pamäť.', 'Nájdite si pokojnú chvíľu, najlepšie večer. Držte sa poradia ráno → doobeda → poobede → večer a pri každej časti položte len jednu úvodnú otázku, napríklad: „Čo bolo ráno?“ Počkajte, kým dieťa dohovorí, a jeho vety nedokončujte. Na záver spolu vyberte najkrajšiu chvíľu dňa a zapíšte ju slovami dieťaťa.', 1, 5, 8, 8, '{"type":"guided_steps","intro":"Porozprávaš mi, aký bol tvoj deň? Pôjdeme pekne po poriadku: ráno, doobeda, poobede a večer.","steps":[{"kicker":"Krok 1 · Naladenie","title":"Ako sa dnes cítiš?","body":"Sadnite si k dieťaťu a povedzte: „Poď mi porozprávať o svojom dni. Ale najprv — ako sa práve teraz cítiš?“ Nechajte dieťa vybrať a pocit spolu pomenujte.","choices":["Veselo","Pokojne","Unavene","Trochu namrzene"]},{"kicker":"Krok 2 · Plán","title":"Deň má štyri časti","body":"Vysvetlite: „Deň si rozdelíme ako koláč na štyri kúsky: ráno, doobeda, poobede a večer.“ Pri každej časti zdvihnite jeden prst — dieťa nech ich zopakuje po vás.","tip":"Ak máte poruke papier, nakreslite štyri okienka — dieťa si do nich môže pri rozprávaní kresliť malé obrázky."},{"kicker":"Krok 3 · Rozprávanie","title":"Rozprávaj po poriadku","body":"Dieťa rozpráva o svojom dni po častiach. Pri každej časti položte len úvodnú otázku: „Čo bolo ráno?“ — a potom počúvajte. Keď časť skončí, presuňte sa na ďalšiu.","tip":"V tichosti vydržte aj dlhšiu pauzu. Nedopĺňajte vety za dieťa — pomôže skôr zopakovanie jeho poslednej vety."},{"kicker":"Krok 4 · Najkrajšia chvíľa","title":"Čo bolo dnes najkrajšie?","body":"Spýtajte sa: „Ktorá chvíľa dňa bola dnes najkrajšia?“ Odpoveď dieťaťa zapíšte jeho vlastnými slovami.","fields":[{"label":"Najkrajšia časť dňa","placeholder":"napr. poobede sme púšťali šarkana s ockom"}]},{"kicker":"Krok 5 · Ukotvenie","title":"Viem rozprávať po poriadku","body":"Pochváľte dieťa konkrétne — pomenujte, že rozprávalo pekne po poriadku od rána až po večer. Spolu nahlas zopakujte: „Svoj deň viem porozprávať krok za krokom.“","fields":[{"label":"Ktorá časť dňa sa rozprávala najľahšie?","placeholder":"napr. ráno — presne vedelo, čo raňajkovalo"}]}]}'::jsonb, true),
('pa-pocitaj-hlasky-1', 'phonemic_awareness', 'interactive', 'Spočítaj hlásky', 'Fonematická analýza krátkych slov — dieťa segmentuje slovo na hlásky a určuje ich počet pomocou žetónov (Eľkoninova metodika, prípravná etapa hláskovej analýzy).', 'Sadnite si vedľa dieťaťa a povedzte slovo najprv prirodzene, potom pomaly a zreteľne: o… k… o. Zopakujte ho spolu a pri každej hláske ťuknite prstom na jeden rámček. Potom sa spýtajte: Koľko hlások sme napočítali? Ak dieťa váha, povedzte slovo ešte pomalšie a hlásky spolu počítajte na prstoch. Chváľte každý pokus, nielen správny výsledok.', 1, 5, 7, 5, '{"type":"sound_boxes","mode":"count","intro":"Každé slovo je poskladané z malých zvukov — hlások. Počúvaj pozorne a spočítaj ich!","items":[{"word":"oko","emoji":"👁️","phonemes":[{"sound":"o","kind":"vowel"},{"sound":"k","kind":"consonant"},{"sound":"o","kind":"vowel"}],"hint":"Povedz slovo pomaličky. Čo počuješ na začiatku, čo v strede a čo na konci?"},{"word":"mak","emoji":"🌸","phonemes":[{"sound":"m","kind":"consonant"},{"sound":"a","kind":"vowel"},{"sound":"k","kind":"consonant"}],"hint":"Natiahni slovo ako žuvačku: mmm… aaa… k. Koľko zvukov počuješ?"},{"word":"dom","emoji":"🏠","phonemes":[{"sound":"d","kind":"consonant"},{"sound":"o","kind":"vowel"},{"sound":"m","kind":"consonant"}],"hint":"Ťukni prstom pri každom zvuku, ktorý v slove počuješ. Koľko ťuknutí to bolo?"},{"word":"syr","emoji":"🧀","phonemes":[{"sound":"s","kind":"consonant"},{"sound":"y","kind":"vowel"},{"sound":"r","kind":"consonant"}],"hint":"Skús slovo povedať pomaly od začiatku až do konca. Koľko hlások po ceste stretneš?"},{"word":"les","emoji":"🌲","phonemes":[{"sound":"l","kind":"consonant"},{"sound":"e","kind":"vowel"},{"sound":"s","kind":"consonant"}],"hint":"Povedz slovo šeptom a pomaly. Koľko zvukov sa v ňom skrýva?"},{"word":"nos","emoji":"👃","phonemes":[{"sound":"n","kind":"consonant"},{"sound":"o","kind":"vowel"},{"sound":"s","kind":"consonant"}],"hint":"Vyslov slovo pomaly a na každú hlásku vystri jeden prst. Koľko prstov máš vystretých?"}]}'::jsonb, true),
('pa-farebne-zetony-2', 'phonemic_awareness', 'interactive', 'Farebné žetóny', 'Fonematická analýza s farebným kódovaním hlások — dieťa rozlišuje krátke a dlhé samohlásky od spoluhlások (Eľkonin–Mikulajová, žetónová etapa).', 'Slovo najprv spoločne rozložte na hlásky. Pri každej hláske sa spýtajte: Dá sa táto hláska zaspievať? Znie krátko, alebo dlho? Dlhé samohlásky spolu poriadne natiahnite: vááá-za. Farbu žetónu vyberajte spoločne a nahlas povedzte prečo. Ak dieťa siahne po nesprávnom žetóne, nezastavujte ho — na konci slovo skontrolujte spolu a nechajte ho chybu nájsť samo.', 2, 6, 9, 6, '{"type":"sound_boxes","mode":"colors","intro":"Každá hláska dostane svoj žetón. Počúvaj, ktorá sa dá spievať, ktorá znie krátko a ktorá dlho!","items":[{"word":"mama","emoji":"👩","phonemes":[{"sound":"m","kind":"consonant"},{"sound":"a","kind":"vowel"},{"sound":"m","kind":"consonant"},{"sound":"a","kind":"vowel"}],"hint":"Ktoré hlásky v slove sa dajú zaspievať? Kde stoja?"},{"word":"ryba","emoji":"🐟","phonemes":[{"sound":"r","kind":"consonant"},{"sound":"y","kind":"vowel"},{"sound":"b","kind":"consonant"},{"sound":"a","kind":"vowel"}],"hint":"Povedz slovo pomaly. Ktoré hlásky znejú krátko a dajú sa spievať?"},{"word":"sova","emoji":"🦉","phonemes":[{"sound":"s","kind":"consonant"},{"sound":"o","kind":"vowel"},{"sound":"v","kind":"consonant"},{"sound":"a","kind":"vowel"}],"hint":"Striedajú sa v slove hlásky, ktoré sa spievať dajú, a tie, ktoré nie?"},{"word":"váza","emoji":"🏺","phonemes":[{"sound":"v","kind":"consonant"},{"sound":"á","kind":"long_vowel"},{"sound":"z","kind":"consonant"},{"sound":"a","kind":"vowel"}],"hint":"Natiahni slovo pomaly. Ktorá hláska znie dlhšie než ostatné?"},{"word":"lúka","emoji":"🌼","phonemes":[{"sound":"l","kind":"consonant"},{"sound":"ú","kind":"long_vowel"},{"sound":"k","kind":"consonant"},{"sound":"a","kind":"vowel"}],"hint":"Počuješ v slove hlásku, ktorá sa ťahá ako dlhá niť?"},{"word":"múr","emoji":"🧱","phonemes":[{"sound":"m","kind":"consonant"},{"sound":"ú","kind":"long_vowel"},{"sound":"r","kind":"consonant"}],"hint":"Ktorá hláska v strede slova znie dlho? Skús ju natiahnuť."}]}'::jsonb, true),
('pa-farebne-zetony-3', 'phonemic_awareness', 'interactive', 'Farebné žetóny pre majstrov', 'Náročnejšia fonematická analýza slov s dvojhláskami (ie) a digrafom ch — dieťa si upevňuje vzťah medzi počutou hláskou a jej zápisom, čo je priama príprava na čítanie a písanie.', 'Povedzte slovo najprv prirodzene, potom po hláskach. Pri dvojhláske dieťaťu ukážte, že dve písmenká môžu znieť ako jeden zvuk: vyslovte mli-e-ko aj mlie-ko a nechajte dieťa porovnať, čo znie správne. Pri slove mucha sa spýtajte: Počuješ ch ako jeden zvuk, alebo ako dva? Žetóny ukladajte spoločne zľava doprava a na konci celé slovo po žetónoch prečítajte.', 3, 7, 10, 8, '{"type":"sound_boxes","mode":"colors","intro":"Slová pre majstrov! Pozor — niekedy dve písmenká znejú spolu ako jeden zvuk.","items":[{"word":"mlieko","emoji":"🥛","phonemes":[{"sound":"m","kind":"consonant"},{"sound":"l","kind":"consonant"},{"sound":"ie","kind":"diphthong"},{"sound":"k","kind":"consonant"},{"sound":"o","kind":"vowel"}],"hint":"Počuješ, ako i a e znejú spolu ako jeden zvuk? Koľko zvukov má potom celé slovo?"},{"word":"hviezda","emoji":"⭐","phonemes":[{"sound":"h","kind":"consonant"},{"sound":"v","kind":"consonant"},{"sound":"ie","kind":"diphthong"},{"sound":"z","kind":"consonant"},{"sound":"d","kind":"consonant"},{"sound":"a","kind":"vowel"}],"hint":"Povedz slovo pomaly. Kde v ňom znejú dve písmenká spolu ako jeden zvuk?"},{"word":"mucha","emoji":"🪰","phonemes":[{"sound":"m","kind":"consonant"},{"sound":"u","kind":"vowel"},{"sound":"ch","kind":"consonant"},{"sound":"a","kind":"vowel"}],"hint":"Počuješ ch ako jeden zvuk, alebo ako dva? Skús ho vysloviť samostatne."},{"word":"žaba","emoji":"🐸","phonemes":[{"sound":"ž","kind":"consonant"},{"sound":"a","kind":"vowel"},{"sound":"b","kind":"consonant"},{"sound":"a","kind":"vowel"}],"hint":"Ktoré hlásky v slove sa dajú zaspievať? Kde stoja?"},{"word":"slnko","emoji":"☀️","phonemes":[{"sound":"s","kind":"consonant"},{"sound":"l","kind":"consonant"},{"sound":"n","kind":"consonant"},{"sound":"k","kind":"consonant"},{"sound":"o","kind":"vowel"}],"hint":"V tomto slove je samohláska až na samom konci. Koľko hlások počuješ pred ňou?"},{"word":"motýľ","emoji":"🦋","phonemes":[{"sound":"m","kind":"consonant"},{"sound":"o","kind":"vowel"},{"sound":"t","kind":"consonant"},{"sound":"ý","kind":"long_vowel"},{"sound":"ľ","kind":"consonant"}],"hint":"Natiahni slovo pomaly. Ktorá hláska v ňom znie dlho ako spev?"}]}'::jsonb, true),
('pa-prva-hlaska-1', 'phonemic_awareness', 'interactive', 'Prvá hláska', 'Izolácia iniciálnej hlásky slova — jeden z najsilnejších prediktorov úspešného osvojenia čítania; dieťa identifikuje slovo začínajúce sa cieľovou hláskou z troch počutých možností.', 'Hlásku vyslovujte vždy ako zvuk (mmm), nie ako názov písmena (em). Prečítajte otázku aj všetky tri slová nahlas. Ak dieťa váha, povedzte každé slovo znova a jeho prvú hlásku zvýraznite — ťahavé hlásky natiahnite (mmmačka, rrryba), ostatné zopakujte samostatne (p — pes). Nechajte dieťa slová zopakovať po vás a až potom vybrať. Pri chybe sa len spýtajte: Naozaj? Skúsme to slovo povedať ešte raz pomaly.', 1, 5, 8, 5, '{"type":"choice","intro":"Nastraž uši! Ktoré slovo sa začína hláskou, ktorú hľadáme?","items":[{"prompt":"Ktoré slovo sa začína hláskou M — mačka, pes alebo ryba?","options":[{"label":"mačka","emoji":"🐱","correct":true},{"label":"pes","emoji":"🐶"},{"label":"ryba","emoji":"🐟"}],"hint":"Povedz každé slovo pomaly a jeho prvú hlásku natiahni. Ktorá znie ako mmm?"},{"prompt":"Ktoré slovo sa začína hláskou S — slon, koza alebo auto?","options":[{"label":"slon","emoji":"🐘","correct":true},{"label":"koza","emoji":"🐐"},{"label":"auto","emoji":"🚗"}],"hint":"Ktoré slovo sa začína zvukom, ktorý syčí ako had — sss?"},{"prompt":"Ktoré slovo sa začína hláskou A — dom, auto alebo mesiac?","options":[{"label":"dom","emoji":"🏠"},{"label":"auto","emoji":"🚗","correct":true},{"label":"mesiac","emoji":"🌙"}],"hint":"Povedz slová nahlas a počúvaj úplne prvý zvuk. Ktorý znie ako aaa?"},{"prompt":"Ktoré slovo sa začína hláskou P — oko, les alebo pes?","options":[{"label":"oko","emoji":"👁️"},{"label":"les","emoji":"🌲"},{"label":"pes","emoji":"🐶","correct":true}],"hint":"Hláska P vybuchne ako malá bublinka na perách. Pri ktorom slove to cítiš?"},{"prompt":"Ktoré slovo sa začína hláskou L — lopta, syr alebo mama?","options":[{"label":"lopta","emoji":"⚽","correct":true},{"label":"syr","emoji":"🧀"},{"label":"mama","emoji":"👩"}],"hint":"Pri hláske L ťukne jazyk hore za predné zúbky. Pri ktorom slove sa ti to stane hneď na začiatku?"},{"prompt":"Ktoré slovo sa začína hláskou O — oko, ucho alebo noha?","options":[{"label":"oko","emoji":"👁️","correct":true},{"label":"ucho","emoji":"👂"},{"label":"noha","emoji":"🦵"}],"hint":"Povedz slová nahlas a počúvaj úplne prvý zvuk. Ktorý znie ako ooo?"},{"prompt":"Ktoré slovo sa začína hláskou K — žaba, kôň alebo vlak?","options":[{"label":"žaba","emoji":"🐸"},{"label":"kôň","emoji":"🐴","correct":true},{"label":"vlak","emoji":"🚂"}],"hint":"Pozor, jedno slovo má hlásku K až na konci! Ktoré ju má hneď na začiatku?"},{"prompt":"Ktoré slovo sa začína hláskou R — slnko, ryba alebo dáždnik?","options":[{"label":"slnko","emoji":"☀️"},{"label":"ryba","emoji":"🐟","correct":true},{"label":"dáždnik","emoji":"☂️"}],"hint":"Hláska R drnčí ako motorček — rrr. Pri ktorom slove ho naštartuješ hneď na začiatku?"}]}'::jsonb, true),
('pa-posledna-hlaska-2', 'phonemic_awareness', 'interactive', 'Posledná hláska', 'Izolácia finálnej hlásky slova — náročnejšia úroveň auditívnej analýzy než iniciálna pozícia; podporuje presnú fonologickú reprezentáciu slova potrebnú pre písanie.', 'Posledná hláska sa hľadá ťažšie než prvá. Povedzte slovo a jeho poslednú hlásku zvýraznite — ťahavé hlásky natiahnite (nosss), ostatné zopakujte samostatne (vlak — k). Ak dieťa váha, vyslovte slovo spoločne a postupne stišujte hlas, takže posledná hláska zaznie ako ozvena. Nesprávnu odpoveď hneď neopravujte — slovo len zopakujte a nechajte dieťa počúvať znova.', 2, 6, 9, 6, '{"type":"choice","intro":"Teraz počúvaj koniec slova. Ktorá hláska zaznie ako posledná?","items":[{"prompt":"Ktoré slovo sa končí hláskou K — vlak, dom alebo les?","options":[{"label":"vlak","emoji":"🚂","correct":true},{"label":"dom","emoji":"🏠"},{"label":"les","emoji":"🌲"}],"hint":"Povedz každé slovo a dobre počúvaj jeho úplne posledný zvuk. Ktorý znie ako k?"},{"prompt":"Ktoré slovo sa končí hláskou S — kôň, nos alebo mak?","options":[{"label":"kôň","emoji":"🐴"},{"label":"nos","emoji":"👃","correct":true},{"label":"mak","emoji":"🌸"}],"hint":"Ktoré slovo na konci syčí ako had — sss?"},{"prompt":"Ktoré slovo sa končí hláskou M — strom, syr alebo lopta?","options":[{"label":"strom","emoji":"🌳","correct":true},{"label":"syr","emoji":"🧀"},{"label":"lopta","emoji":"⚽"}],"hint":"Pri ktorom slove máš na konci zavreté pery a zvuk ti bzučí v nose — mmm?"},{"prompt":"Ktoré slovo sa končí hláskou A — oko, slon alebo ryba?","options":[{"label":"oko","emoji":"👁️"},{"label":"slon","emoji":"🐘"},{"label":"ryba","emoji":"🐟","correct":true}],"hint":"Povedz slová pomaly a posledný zvuk natiahni. Ktorý znie ako aaa?"},{"prompt":"Ktoré slovo sa končí hláskou R — mama, syr alebo vlak?","options":[{"label":"mama","emoji":"👩"},{"label":"syr","emoji":"🧀","correct":true},{"label":"vlak","emoji":"🚂"}],"hint":"Ktoré slovo má na konci drnčiaci motorček — rrr?"},{"prompt":"Ktoré slovo sa končí hláskou O — žaba, auto alebo les?","options":[{"label":"žaba","emoji":"🐸"},{"label":"auto","emoji":"🚗","correct":true},{"label":"les","emoji":"🌲"}],"hint":"Pri ktorom slove sa ti ústa na konci zaokrúhlia ako koliesko?"},{"prompt":"Ktoré slovo sa končí hláskou N — pes, ruka alebo slon?","options":[{"label":"pes","emoji":"🐶"},{"label":"ruka","emoji":"✋"},{"label":"slon","emoji":"🐘","correct":true}],"hint":"Povedz slová pomaly a poslednú hlásku podrž. Ktorá ti bzučí v nose ako nnn?"},{"prompt":"Ktoré slovo sa končí hláskou Š — koza, myš alebo strom?","options":[{"label":"koza","emoji":"🐐"},{"label":"myš","emoji":"🐭","correct":true},{"label":"strom","emoji":"🌳"}],"hint":"Ktoré slovo na konci šumí ako vlak — ššš?"}]}'::jsonb, true),
('pa-rymy-1', 'phonemic_awareness', 'interactive', 'Rýmovačky', 'Identifikácia rýmu — epilingvistická úroveň fonologického uvedomovania; dieťa porovnáva zvukové zakončenia slov, čo pripravuje neskoršiu analýzu na úrovni hlások.', 'Prečítajte slovo aj všetky tri možnosti nahlas, rytmicky, akoby ste recitovali riekanku. Spýtajte sa: Ktoré dve slová znejú na konci rovnako? Ak dieťa váha, povedzte dvojice za sebou (mak — dom, mak — rak) a nechajte ho počúvať, ktorá dvojica znie ako pesnička. Rýmujúcu dvojicu si na záver spolu veselo zopakujte.', 1, 5, 7, 5, '{"type":"choice","intro":"Rýmy sú slová, ktoré znejú na konci rovnako — ako v riekanke. Nájdeš ich?","items":[{"prompt":"Čo sa rýmuje so slovom mak — rak, dom alebo syr?","options":[{"label":"rak","emoji":"🦞","correct":true},{"label":"dom","emoji":"🏠"},{"label":"syr","emoji":"🧀"}],"hint":"Povedz slová za sebou ako riekanku. Ktorá dvojica znie na konci rovnako?"},{"prompt":"Čo sa rýmuje so slovom pes — mačka, les alebo auto?","options":[{"label":"mačka","emoji":"🐱"},{"label":"les","emoji":"🌲","correct":true},{"label":"auto","emoji":"🚗"}],"hint":"Skús dvojice: pes — mačka, pes — les, pes — auto. Ktorá znie ako pesnička?"},{"prompt":"Čo sa rýmuje so slovom mačka — pes, slon alebo kačka?","options":[{"label":"pes","emoji":"🐶"},{"label":"slon","emoji":"🐘"},{"label":"kačka","emoji":"🦆","correct":true}],"hint":"Počúvaj konce slov: -čka. Ktoré slovo končí rovnako ako mačka?"},{"prompt":"Čo sa rýmuje so slovom dom — strom, ryba alebo oko?","options":[{"label":"strom","emoji":"🌳","correct":true},{"label":"ryba","emoji":"🐟"},{"label":"oko","emoji":"👁️"}],"hint":"Povedz slová nahlas a počúvaj ich konce. Ktoré slovo znie na konci ako dom?"},{"prompt":"Čo sa rýmuje so slovom nos — ucho, kos alebo noha?","options":[{"label":"ucho","emoji":"👂"},{"label":"kos","emoji":"🐦","correct":true},{"label":"noha","emoji":"🦵"}],"hint":"Skús dvojice povedať ako básničku: nos — ucho, nos — kos. Ktorá sa ti rýmuje?"},{"prompt":"Čo sa rýmuje so slovom myška — slon, vlak alebo líška?","options":[{"label":"slon","emoji":"🐘"},{"label":"vlak","emoji":"🚂"},{"label":"líška","emoji":"🦊","correct":true}],"hint":"Počúvaj konce slov: -ška. Ktoré slovo končí rovnako ako myška?"},{"prompt":"Čo sa rýmuje so slovom vlak — slnko, mrak alebo kniha?","options":[{"label":"slnko","emoji":"☀️"},{"label":"mrak","emoji":"☁️","correct":true},{"label":"kniha","emoji":"📖"}],"hint":"Povedz dvojice nahlas: vlak — slnko, vlak — mrak. Ktorá znie ako riekanka?"},{"prompt":"Čo sa rýmuje so slovom žaba — strom, baba alebo myš?","options":[{"label":"strom","emoji":"🌳"},{"label":"baba","emoji":"👵","correct":true},{"label":"myš","emoji":"🐭"}],"hint":"Počúvaj konce slov: -aba. Ktoré slovo končí rovnako ako žaba?"}]}'::jsonb, true),
('pa-slabiky-1', 'phonemic_awareness', 'interactive', 'Vytlieskaj slabiky', 'Slabičná analýza s motorickou oporou (vytlieskavanie) — východisková úroveň fonologického uvedomovania; dieťa určuje počet slabík v slove.', 'Slovo najprv povedzte celé a potom ho spoločne vytlieskajte — pri každej slabike jedno tlesknutie. Tlesknutia počítajte nahlas spolu. Ak dieťa tlieska inak, chyťte jeho dlane do svojich a vytlieskajte slovo spoločne ešte raz, pomaly. Číslo nechajte vybrať dieťa — vy len tlieskate a počúvate.', 1, 5, 7, 5, '{"type":"choice","intro":"Každé slovo sa dá vytlieskať po kúskoch — slabikách. Tlieskaj a počítaj!","items":[{"prompt":"Vytlieskaj slovo mak. Koľko slabík má?","options":[{"label":"1","emoji":"1️⃣","correct":true},{"label":"2","emoji":"2️⃣"},{"label":"3","emoji":"3️⃣"}],"hint":"Tlieskaj a hovor: mak. Koľko tlesknutí to bolo?"},{"prompt":"Vytlieskaj slovo ryba. Koľko slabík má?","options":[{"label":"1","emoji":"1️⃣"},{"label":"2","emoji":"2️⃣","correct":true},{"label":"3","emoji":"3️⃣"}],"hint":"Tlieskaj a hovor: ry — ba. Koľko tlesknutí to bolo?"},{"prompt":"Vytlieskaj slovo koleso. Koľko slabík má?","options":[{"label":"2","emoji":"2️⃣"},{"label":"3","emoji":"3️⃣","correct":true},{"label":"4","emoji":"4️⃣"}],"hint":"Tlieskaj a hovor: ko — le — so. Koľko tlesknutí to bolo?"},{"prompt":"Vytlieskaj slovo pes. Koľko slabík má?","options":[{"label":"1","emoji":"1️⃣","correct":true},{"label":"2","emoji":"2️⃣"},{"label":"3","emoji":"3️⃣"}],"hint":"Tlieskaj a hovor: pes. Stačilo jedno tlesknutie, alebo viac?"},{"prompt":"Vytlieskaj slovo čokoláda. Koľko slabík má?","options":[{"label":"2","emoji":"2️⃣"},{"label":"3","emoji":"3️⃣"},{"label":"4","emoji":"4️⃣","correct":true}],"hint":"Tlieskaj a hovor: čo — ko — lá — da. Koľko tlesknutí to bolo?"},{"prompt":"Vytlieskaj slovo banán. Koľko slabík má?","options":[{"label":"1","emoji":"1️⃣"},{"label":"2","emoji":"2️⃣","correct":true},{"label":"3","emoji":"3️⃣"}],"hint":"Tlieskaj a hovor: ba — nán. Koľko tlesknutí to bolo?"},{"prompt":"Vytlieskaj slovo motorka. Koľko slabík má?","options":[{"label":"2","emoji":"2️⃣"},{"label":"3","emoji":"3️⃣","correct":true},{"label":"4","emoji":"4️⃣"}],"hint":"Tlieskaj a hovor: mo — tor — ka. Koľko tlesknutí to bolo?"},{"prompt":"Vytlieskaj slovo paradajka. Koľko slabík má?","options":[{"label":"2","emoji":"2️⃣"},{"label":"3","emoji":"3️⃣"},{"label":"4","emoji":"4️⃣","correct":true}],"hint":"Tlieskaj a hovor: pa — ra — daj — ka. Koľko tlesknutí to bolo?"}]}'::jsonb, true),
('pa-skladanie-hlasok-2', 'phonemic_awareness', 'speech', 'Poskladaj slovo', 'Fonematická syntéza — spájanie izolovane prezentovaných hlások do slova; zručnosť priamo podporujúca dekódovanie pri čítaní.', 'Hlásky vyslovujte ako zvuky (nie názvy písmen), pomaly a s krátkou pauzou: m… a… k. Ak dieťa slovo nezloží, pauzy postupne skracujte a hlásky spájajte: ma… k, mak. Nechajte dieťa slovo najprv povedať nahlas a až potom vybrať obrázok. Keď sa mu darí, pauzy medzi hláskami naopak predlžujte.', 2, 6, 9, 6, '{"type":"speech_items","intro":"Poviem ti slovo po jednotlivých hláskach. Poskladáš ho a povieš, aké slovo to je?","items":[{"ask":"Aké slovo poviem? P — E — S","text":"pes","emoji":"🐶","tip":"Povedz hlásky za sebou stále rýchlejšie. Aké slovo ti z nich vyskočí?"},{"ask":"Aké slovo poviem? M — A — K","text":"mak","emoji":"🌸","tip":"Zopakuj hlásky so mnou a spájaj ich k sebe. Čo ti vyšlo?"},{"ask":"Aké slovo poviem? D — O — M","text":"dom","emoji":"🏠","tip":"Povedz hlásky d – o – m rýchlo za sebou. Čo ti vyšlo?"},{"ask":"Aké slovo poviem? R — Y — B — A","text":"ryba","emoji":"🐟","tip":"Povedz hlásky spolu ako jedno slovo. Čo ti vyšlo?"},{"ask":"Aké slovo poviem? O — K — O","text":"oko","emoji":"👁️","tip":"Slovo sa začína aj končí rovnakou hláskou. Ktoré to je?"},{"ask":"Aké slovo poviem? S — O — V — A","text":"sova","emoji":"🦉","tip":"Počúvaj prvú hlásku. Ktoré zviera sa ňou začína?"},{"ask":"Aké slovo poviem? V — L — A — K","text":"vlak","emoji":"🚂","tip":"Spoj hlásky do jedného slova. Čo z nich vzniklo?"},{"ask":"Aké slovo poviem? Ž — A — B — A","text":"žaba","emoji":"🐸","tip":"Povedz hlásky rýchlo za sebou. Ktoré zviera tak skáče z tvojich úst?"}]}'::jsonb, true),
('pa-vynechaj-hlasku-3', 'phonemic_awareness', 'speech', 'Kúzelník hlások — schovaj hlásku', 'Elízia iniciálnej hlásky — najvyššia úroveň fonematického uvedomovania (fonematická manipulácia). Každá položka vedie k reálnemu slovu, takže dieťa priamo počuje význam operácie a jej dôsledok.', 'Povedzte slovo zreteľne a spýtajte sa: „Povedz vlak — ale bez v.“ Doprajte dieťaťu veľa času. Ak sa nedarí, povedzte slovo pomaly po hláskach (v — l — a — k), prvú hlásku len zašepkajte a zvyšok povedzte nahlas. Výsledok nikdy neprezraďte — nech nové slovo objaví dieťa samo a tešte sa spolu, že sa z jedného slova vyčarovalo druhé.', 3, 7, 10, 6, '{"type":"speech_items","intro":"Si kúzelník hlások! Schovaj prvú hlásku a z jedného slova vyčaruješ úplne iné.","items":[{"text":"vlak — povedz bez V","emoji":"🚂","tip":"Správne: lak. Ak sa nedarí, povedzte pomaly v — lak a prvú hlásku zašepkajte."},{"text":"mrak — povedz bez M","emoji":"☁️","tip":"Správne: rak. Spýtajte sa: „Aké zvieratko sa skrývalo v mraku?“"},{"text":"hrad — povedz bez H","emoji":"🏰","tip":"Správne: rad."},{"text":"plot — povedz bez P","emoji":"🚧","tip":"Správne: lot."},{"text":"kosa — povedz bez K","emoji":"🌾","tip":"Správne: osa. „Čo bzučalo v kose?“"},{"text":"smech — povedz bez S","emoji":"😂","tip":"Správne: mech."},{"text":"slama — povedz bez S","emoji":"🌾","tip":"Správne: lama. „Aké zvieratko sa schovalo v slame?“"},{"text":"krok — povedz bez K","emoji":"👣","tip":"Správne: rok. Najťažšia položka — pokojne zopakujte slovo po hláskach."}]}'::jsonb, true),
('pa-vymen-hlasku-3', 'phonemic_awareness', 'speech', 'Kúzelník hlások — vymeň hlásku', 'Substitúcia hlásky v iniciálnej, mediálnej aj finálnej pozícii s oporou o minimálne páry — komplexná fonematická manipulácia, ktorá završuje hierarchiu fonematického uvedomovania.', 'Povedzte pokyn presne: „Povedz mak — ale namiesto m daj r.“ Hlásky vyslovujte ako zvuky (m, r), nie ako názvy písmen (em, er). Nechajte dieťa slovo vysloviť a spolu objavte, čo znamená. Ak sa nedarí, povedzte slovo pomaly po hláskach a pri vymieňanej hláske sa zastavte. Výsledok neprezrádzajte.', 3, 7, 10, 6, '{"type":"speech_items","intro":"Vymeň jednu jedinú hlásku — a slovo sa premení na úplne iné!","items":[{"text":"mak — namiesto M daj R","emoji":"🌸","tip":"Správne: rak. Začíname výmenou prvej hlásky — tá je najľahšia."},{"text":"les — namiesto L daj P","emoji":"🌲","tip":"Správne: pes."},{"text":"rok — namiesto O daj A","emoji":"📅","tip":"Správne: rak. Výmena v strede slova je ťažšia — pokojne slovo rozložte: r — o — k."},{"text":"sud — namiesto U daj A","emoji":"🛢️","tip":"Správne: sad."},{"text":"lak — namiesto A daj U","emoji":"💅","tip":"Správne: luk."},{"text":"kosa — namiesto S daj Z","emoji":"🌾","tip":"Správne: koza. Rozdiel s/z je len v zapnutí hlasu — nech si dieťa priloží ruku na krk."},{"text":"nos — namiesto S daj C","emoji":"👃","tip":"Správne: noc. Výmena poslednej hlásky."},{"text":"píla — namiesto P daj S","emoji":"🪚","tip":"Správne: sila."}]}'::jsonb, true),
('vo-co-nepatri-1', 'vocabulary', 'interactive', 'Čo medzi ostatné nepatrí?', 'Sémantická klasifikácia na úrovni základných kategórií: dieťa vylučuje položku, ktorá nepatrí do skupiny. Buduje nadradené pojmy a organizáciu slovnej zásoby.', 'Pomaly prečítajte všetky štyri slová a pri každom ukážte na obrázok. Ak si dieťa nie je isté, vymenujte tri podobné veci ešte raz a spýtajte sa: „Čo majú tieto tri spoločné?“ Keď dieťa ukáže odpoveď, poproste ho, aby povedalo prečo, a spolu sa potešte: „Áno, presne tak!“', 1, 5, 7, 5, '{"type":"choice","intro":"Pozri sa na obrázky. Tri veci k sebe patria a jedna sa medzi ne zatúlala. Nájdeš ju?","items":[{"prompt":"Počúvaj: pes, mačka, krava a auto. Čo medzi ostatné nepatrí?","options":[{"label":"pes","emoji":"🐶"},{"label":"mačka","emoji":"🐱"},{"label":"krava","emoji":"🐮"},{"label":"auto","emoji":"🚗","correct":true}],"hint":"Tri z nich vedia behať a papať. Ktorá vec to nevie?"},{"prompt":"Počúvaj: jablko, banán, hruška a stolička. Čo medzi ostatné nepatrí?","options":[{"label":"jablko","emoji":"🍎"},{"label":"banán","emoji":"🍌"},{"label":"hruška","emoji":"🍐"},{"label":"stolička","emoji":"🪑","correct":true}],"hint":"Do troch z nich si môžeš zahryznúť. Ktorú vec nezješ?"},{"prompt":"Počúvaj: tričko, čiapka, topánka a banán. Čo medzi ostatné nepatrí?","options":[{"label":"tričko","emoji":"👕"},{"label":"čiapka","emoji":"🧢"},{"label":"topánka","emoji":"👟"},{"label":"banán","emoji":"🍌","correct":true}],"hint":"Tri veci si ráno obliekaš alebo obúvaš. Ktorú si na seba nedáš?"},{"prompt":"Počúvaj: auto, vlak, lietadlo a mačka. Čo medzi ostatné nepatrí?","options":[{"label":"auto","emoji":"🚗"},{"label":"vlak","emoji":"🚂"},{"label":"lietadlo","emoji":"✈️"},{"label":"mačka","emoji":"🐱","correct":true}],"hint":"Tromi z nich sa môžeš odviezť na výlet. Čo z toho ťa neodvezie?"},{"prompt":"Počúvaj: lyžica, vidlička, tanier a lopta. Čo medzi ostatné nepatrí?","options":[{"label":"lyžica","emoji":"🥄"},{"label":"vidlička","emoji":"🍴"},{"label":"tanier","emoji":"🍽️"},{"label":"lopta","emoji":"⚽","correct":true}],"hint":"Tri veci nájdeš na stole pri obede. Ktorá tam nepatrí?"},{"prompt":"Počúvaj: slon, žirafa, lev a jahoda. Čo medzi ostatné nepatrí?","options":[{"label":"slon","emoji":"🐘"},{"label":"žirafa","emoji":"🦒"},{"label":"lev","emoji":"🦁"},{"label":"jahoda","emoji":"🍓","correct":true}],"hint":"Tri z nich uvidíš v zoo. Ktorú tam nenájdeš?"},{"prompt":"Počúvaj: ruža, tulipán, slnečnica a autobus. Čo medzi ostatné nepatrí?","options":[{"label":"ruža","emoji":"🌹"},{"label":"tulipán","emoji":"🌷"},{"label":"slnečnica","emoji":"🌻"},{"label":"autobus","emoji":"🚌","correct":true}],"hint":"Tri z nich rastú v záhrade a voňajú. Ktorá vec nerastie?"},{"prompt":"Počúvaj: lopta, medvedík, šarkan a mrkva. Čo medzi ostatné nepatrí?","options":[{"label":"lopta","emoji":"⚽"},{"label":"medvedík","emoji":"🧸"},{"label":"šarkan","emoji":"🪁"},{"label":"mrkva","emoji":"🥕","correct":true}],"hint":"S tromi z nich sa môžeš hrať. Čo z toho nie je na hranie?"}]}'::jsonb, true),
('vo-co-nepatri-3', 'vocabulary', 'interactive', 'Zatúlané slovo', 'Vylučovanie podľa jemnejších sémantických kritérií (ovocie vs. zelenina, lietajúce vs. nelietajúce, domáce vs. divé). Prehlbuje pojmovú diferenciáciu a flexibilitu kategorizácie.', 'Prečítajte všetky štyri slová a nechajte dieťa chvíľu premýšľať — skupiny sú tu záludnejšie. Ak váha, prečítajte pomocnú otázku: pomenúva, podľa čoho sa veci delia. Po odpovedi poproste dieťa o zdôvodnenie celou vetou: „Nepatrí tam, lebo…“ Ak sa pomýli, neprezrádzajte — vráťte sa k pomocnej otázke a skúste to spolu ešte raz.', 3, 7, 10, 6, '{"type":"choice","intro":"Toto sú hádanky pre bystré hlavičky. Jedno slovo sa medzi ostatné zatúlalo — musíš dobre premýšľať, prečo!","items":[{"prompt":"Počúvaj: jablko, hruška, čerešňa a mrkva. Čo medzi ostatné nepatrí?","options":[{"label":"jablko","emoji":"🍎"},{"label":"hruška","emoji":"🍐"},{"label":"čerešňa","emoji":"🍒"},{"label":"mrkva","emoji":"🥕","correct":true}],"hint":"Čo z toho je ovocie a čo zelenina?"},{"prompt":"Počúvaj: motýľ, včela, vtáčik a slimák. Čo medzi ostatné nepatrí?","options":[{"label":"motýľ","emoji":"🦋"},{"label":"včela","emoji":"🐝"},{"label":"vtáčik","emoji":"🐦"},{"label":"slimák","emoji":"🐌","correct":true}],"hint":"Ktoré z nich vedia lietať a ktoré nie?"},{"prompt":"Počúvaj: pes, mačka, kôň a vlk. Čo medzi ostatné nepatrí?","options":[{"label":"pes","emoji":"🐶"},{"label":"mačka","emoji":"🐱"},{"label":"kôň","emoji":"🐴"},{"label":"vlk","emoji":"🐺","correct":true}],"hint":"Ktoré zvieratá žijú s ľuďmi doma či na dvore a ktoré v divokej prírode?"},{"prompt":"Počúvaj: rukavice, šál, kabát a plavky. Čo medzi ostatné nepatrí?","options":[{"label":"rukavice","emoji":"🧤"},{"label":"šál","emoji":"🧣"},{"label":"kabát","emoji":"🧥"},{"label":"plavky","emoji":"🩱","correct":true}],"hint":"Čo si obliekaš v zime a čo v lete?"},{"prompt":"Počúvaj: gitara, bubon, trúbka a kladivo. Čo medzi ostatné nepatrí?","options":[{"label":"gitara","emoji":"🎸"},{"label":"bubon","emoji":"🥁"},{"label":"trúbka","emoji":"🎺"},{"label":"kladivo","emoji":"🔨","correct":true}],"hint":"Na čom z toho sa dá zahrať pesnička a na čom nie?"},{"prompt":"Počúvaj: bicykel, skejtbord, kolobežka a sánky. Čo medzi ostatné nepatrí?","options":[{"label":"bicykel","emoji":"🚲"},{"label":"skejtbord","emoji":"🛹"},{"label":"kolobežka","emoji":"🛴"},{"label":"sánky","emoji":"🛷","correct":true}],"hint":"Ktoré z nich majú kolesá a ktoré sa kĺžu po snehu?"},{"prompt":"Počúvaj: syr, maslo, mlieko a chlieb. Čo medzi ostatné nepatrí?","options":[{"label":"syr","emoji":"🧀"},{"label":"maslo","emoji":"🧈"},{"label":"mlieko","emoji":"🥛"},{"label":"chlieb","emoji":"🍞","correct":true}],"hint":"Čo z toho máme vďaka kravičke a čo sa pečie z múky?"},{"prompt":"Počúvaj: čaj, polievka, kakao a zmrzlina. Čo medzi ostatné nepatrí?","options":[{"label":"čaj","emoji":"☕"},{"label":"polievka","emoji":"🍲"},{"label":"kakao","emoji":"🍵"},{"label":"zmrzlina","emoji":"🍦","correct":true}],"hint":"Čo z toho je horúce a čo studené?"}]}'::jsonb, true),
('vo-protiklady-1', 'vocabulary', 'speech', 'Slová naopak', 'Antonymá — dieťa nahlas hovorí protiklad k slovu. Rozširuje slovník prídavných mien a prísloviek a upevňuje chápanie sémantických vzťahov.', 'Slovo prečítajte pomaly a zahrajte ho telom: pri slove veľký sa vystrite a rozpažte, pri slove malý sa prikrčte. Ak dieťa váha, povedzte vetu s medzerou na doplnenie: „Slon je veľký a myška je…?“ a nechajte dieťa vetu dokončiť. Správnu odpoveď spolu zopakujte v celej vete.', 1, 5, 7, 5, '{"type":"speech_items","intro":"Zahráme sa na slová naopak. Poviem ti slovo a ty povieš jeho opak!","items":[{"ask":"Aký je opak slova veľký?","text":"malý","emoji":"🐭","tip":"Slon je veľký. Aká je myška?"},{"ask":"Aký je opak slova horúci?","text":"studený","emoji":"❄️","tip":"Čaj je horúci. Aká je zmrzlina?"},{"ask":"Čo je opakom slova deň?","text":"noc","emoji":"🌙","tip":"Cez deň svieti slnko. Čo je vtedy, keď svieti mesiac a hviezdy?"},{"ask":"Aký je opak slova rýchly?","text":"pomalý","emoji":"🐌","tip":"Zajac beží rýchlo. Ako sa pohybuje slimák?"},{"ask":"Aký je opak slova veselý?","text":"smutný","emoji":"😢","tip":"Keď sa smeješ, si veselý. Aký si, keď plačeš?"},{"ask":"Čo je opakom slova hore?","text":"dole","emoji":"⬇️","tip":"Vtáčik vyletí hore na strom. Kam padá list zo stromu?"},{"ask":"Aký je opak slova ťažký?","text":"ľahký","emoji":"🪶","tip":"Kameň je ťažký. Aké je pierko?"},{"ask":"Aký je opak slova starý?","text":"mladý","emoji":"👶","tip":"Dedko je starý. Aké je bábätko?"}]}'::jsonb, true),
('vo-kategorie-2', 'vocabulary', 'interactive', 'Kam to patrí?', 'Priraďovanie slov k miestam a témam (kuchyňa, les, zima). Upevňuje sémantické polia a kontextovú organizáciu slovnej zásoby.', 'Otázku prečítajte a nechajte dieťa najprv hádať samo. Ak váha, spolu si miesto predstavte: „Zavri oči. Sme v kuchyni. Čo tam vidíš? Čo tam vonia?“ Po správnej odpovedi poproste dieťa, aby vymenovalo ešte jednu vec, ktorá tam tiež patrí — tým si slovnú zásobu upevní.', 2, 5, 9, 5, '{"type":"choice","intro":"Každá vec má svoje miesto. Uhádneš, čo kam patrí?","items":[{"prompt":"Čo patrí do kuchyne?","options":[{"label":"hrniec","emoji":"🍲","correct":true},{"label":"vankúš","emoji":"🛏️"},{"label":"kolobežka","emoji":"🛴"}],"hint":"Predstav si, ako sa varí polievka. Čo je na to potrebné?"},{"prompt":"Čo patrí do lesa?","options":[{"label":"veverička","emoji":"🐿️","correct":true},{"label":"televízor","emoji":"📺"},{"label":"plavky","emoji":"🩱"}],"hint":"Čo z toho môžeš stretnúť medzi stromami?"},{"prompt":"Čo patrí k zime?","options":[{"label":"snehuliak","emoji":"⛄","correct":true},{"label":"motýľ","emoji":"🦋"},{"label":"jahody","emoji":"🍓"}],"hint":"Čo z toho uvidíš vonku, keď sneží?"},{"prompt":"Čo patrí do kúpeľne?","options":[{"label":"zubná kefka","emoji":"🪥","correct":true},{"label":"lyžica","emoji":"🥄"},{"label":"lopta","emoji":"⚽"}],"hint":"Čo z toho používaš každý večer pri umývaní?"},{"prompt":"Čo patrí na oblohu?","options":[{"label":"mrak","emoji":"☁️","correct":true},{"label":"ryba","emoji":"🐟"},{"label":"stolička","emoji":"🪑"}],"hint":"Čo z toho uvidíš, keď sa pozrieš hore na oblohu?"},{"prompt":"Čo patrí do mora?","options":[{"label":"chobotnica","emoji":"🐙","correct":true},{"label":"ťava","emoji":"🐫"},{"label":"sova","emoji":"🦉"}],"hint":"Kto z nich vie plávať hlboko pod vodou?"},{"prompt":"Čo patrí do školy?","options":[{"label":"aktovka","emoji":"🎒","correct":true},{"label":"hrniec","emoji":"🍲"},{"label":"sánky","emoji":"🛷"}],"hint":"Čo z toho potrebuje školák na vyučovaní?"},{"prompt":"Čo patrí k letu?","options":[{"label":"slnečné okuliare","emoji":"🕶️","correct":true},{"label":"rukavice","emoji":"🧤"},{"label":"snehuliak","emoji":"⛄"}],"hint":"Čo z toho si berieš von, keď silno svieti slniečko?"}]}'::jsonb, true),
('vo-hadanky-2', 'vocabulary', 'speech', 'Hádanky', 'Počúvanie s porozumením a inferencia: dieťa spája viacero vlastností z opisu do jedného pojmu. Rozvíja porozumenie súvislej reči a aktívny slovník.', 'Hádanku prečítajte pomaly a s tajomným hlasom, pokojne aj dvakrát. Ak dieťa nevie, zopakujte ju po častiach a pri každej sa spýtajte: „Kto to robí? Kto tak vyzerá?“ Nechajte dieťa hádať bez náhlenia — hádanie je hra, nie skúšanie. Na záver nech dieťa hádanku zopakuje vlastnými slovami.', 2, 5, 9, 6, '{"type":"speech_items","intro":"Mám pre teba hádanky! Dobre počúvaj a uhádni, o kom alebo o čom hovorím.","items":[{"ask":"Má štyri nohy, šteká a stráži dom. Kto je to?","text":"pes","emoji":"🐶","tip":"Zvieratko, ktoré šteká a stráži dom."},{"ask":"Je oranžová, chrumkavá a rastie v zemi. Zajačik ju rád chrúme. Čo je to?","text":"mrkva","emoji":"🥕","tip":"Je oranžová, rastie v zemi a zajačik ju rád chrúme."},{"ask":"V noci svieti na oblohe a cez deň sa schová. Čo je to?","text":"mesiac","emoji":"🌙","tip":"Čo vidíš na oblohe, keď je tma?"},{"ask":"Má veľmi dlhý krk a vidí ponad všetky stromy. Kto je to?","text":"žirafa","emoji":"🦒","tip":"Zviera s najdlhším krkom — vidí ponad stromy."},{"ask":"Padá z neba, je biely a studený. V zime z neho staviame snehuliaka. Čo je to?","text":"sneh","emoji":"❄️","tip":"Je biely, studený a padá z neba."},{"ask":"Má dve kolesá a zvonček. Šliapeš na ňom do pedálov. Čo je to?","text":"bicykel","emoji":"🚲","tip":"Má dve kolesá a šliapeš do pedálov."},{"ask":"Býva v úli, bzučí a vyrába sladký med. Kto je to?","text":"včela","emoji":"🐝","tip":"Bzučí, býva v úli a vyrába med."},{"ask":"Keď prší, roztvoríš ho a držíš nad hlavou, aby na teba nepršalo. Čo je to?","text":"dáždnik","emoji":"☂️","tip":"Držíš ho nad hlavou, keď prší."}]}'::jsonb, true),
('vo-vymenuj-2', 'vocabulary', 'speech', 'Vymenuj čo najviac', 'Verbálna fluencia — generatívne menovanie v sémantických kategóriách. Ukazovateľ dostupnosti a organizácie lexikónu; posilňuje lexikálne vybavovanie.', 'Zadajte kategóriu a pre rozbeh povedzte jedno slovo ako príklad. Slová dieťaťa počítajte nahlas na prstoch, nech vidí, ako mu pribúdajú body. Keď sa zasekne, pomôžte otázkou: „A čo vidíš v izbe? Čo máme na dvore?“ Pochváľte každé slovo — počet je hra, nie skúška.', 2, 5, 9, 8, '{"type":"speech_items","intro":"Zahráme sa na zbieranie slov. Vymenuj čo najviac vecí — každé slovo je jeden bod!","items":[{"text":"Vymenuj čo najviac zvierat.","emoji":"🐾","tip":"Cieľ je aspoň 6 slov — počítajte ich na prstoch. Ak sa dieťa zasekne, spýtajte sa: „A čo žije vo vode? Čo lieta?“"},{"text":"Vymenuj čo najviac farieb.","emoji":"🎨","tip":"Cieľ okolo 6 slov. Pomôžte otázkou: „Akú farbu má tvoje tričko? A obloha? A tráva?“"},{"text":"Vymenuj čo najviac vecí, ktoré nájdeš v kuchyni.","emoji":"🍳","tip":"Počítajte na prstoch, cieľ aspoň 6. Pomôžte otázkou: „Čo potrebuješ na polievku? Z čoho ješ a piješ?“"},{"text":"Vymenuj čo najviac druhov ovocia a zeleniny.","emoji":"🍎","tip":"Cieľ 6 a viac. Pomôže predstava obchodu: „Ideme nakupovať — čo dáme do košíka?“"},{"text":"Vymenuj čo najviac kusov oblečenia.","emoji":"👕","tip":"Cieľ okolo 6 slov. Pomôžte otázkou: „Čo si obliekaš ráno? A čo navyše v zime?“"},{"text":"Vymenuj čo najviac hračiek.","emoji":"🧸","tip":"Cieľ aspoň 6. Ak treba, spýtajte sa: „S čím sa hráš vonku? Čo máš v izbe na poličke?“"}]}'::jsonb, true),
('vo-nadradene-slova-3', 'vocabulary', 'speech', 'Jedným slovom', 'Nadradené pojmy — dieťa zovšeobecňuje skupinu slov do kategórie. Kľúčové pre hierarchickú organizáciu lexikónu a neskoršie definičné schopnosti.', 'Tri slová vymenujte pomaly, pri každom urobte malú pauzu a spýtajte sa: „Ako ich nazveme jedným slovom?“ Ak dieťa váha, pridajte ďalší príklad z rovnakej skupiny a spýtajte sa, kde všetky tieto veci nájdeme. Na záver nech dieťa samo vymyslí ešte jednu vec z tej istej skupiny.', 3, 7, 10, 6, '{"type":"speech_items","intro":"Niektoré slová sú ako kúzelné vrecúška — zmestí sa do nich veľa vecí naraz. Skús ich nájsť!","items":[{"ask":"Jablko, hruška a slivka — ako sa volajú jedným slovom?","text":"ovocie","emoji":"🍎","tip":"Všetky rastú na stromoch v sade. Aká je to skupina?"},{"ask":"Pes, mačka a zajac — ako ich nazveme jedným slovom?","text":"zvieratá","emoji":"🐾","tip":"Všetky sú živé, majú srsť a štyri nohy. Do akej skupiny patria?"},{"ask":"Tričko, nohavice a ponožky — čo je to jedným slovom?","text":"oblečenie","emoji":"👕","tip":"Čo so všetkými robíme každé ráno, keď vstaneme?"},{"ask":"Stôl, stolička a skriňa — ako sa volajú jedným slovom?","text":"nábytok","emoji":"🪑","tip":"Všetky stoja v izbe a bývajú z dreva. Aká je to skupina?"},{"ask":"Auto, vlak a lietadlo — čo je to jedným slovom?","text":"dopravné prostriedky","emoji":"🚗","tip":"Na čo nám všetky slúžia, keď ideme na výlet?"},{"ask":"Mrkva, uhorka a kapusta — ako ich nazveme jedným slovom?","text":"zelenina","emoji":"🥕","tip":"Všetky rastú v záhradke na hriadke a dávame ich do šalátu. Aká je to skupina?"},{"ask":"Gitara, bubon a trúbka — čo je to jedným slovom?","text":"hudobné nástroje","emoji":"🎸","tip":"Čo so všetkými robíme, keď chceme počuť hudbu?"},{"ask":"Ruža, tulipán a slnečnica — ako sa volajú jedným slovom?","text":"kvety","emoji":"🌷","tip":"Voňajú, majú lupienky a dávame ich do vázy. Aká je to skupina?"}]}'::jsonb, true),
('wm-zapamataj-poradie-1', 'working_memory', 'interactive', 'Zapamätaj si poradie — prvé kroky', 'Tréning vizuálnej sekvenčnej pamäti na krátkych radoch (2 – 3 prvky). Buduje kapacitu krátkodobej pamäti a schopnosť udržať sériové poradie podnetov.', 'Sadnite si vedľa dieťaťa a povedzte: „Obrázky sa nám ukážu len na chvíľku. Poď, pomenujeme ich spolu nahlas.“ Kým sú obrázky viditeľné, pomenujte ich s dieťaťom: „pes — jablko“. Potom nechajte dieťa ukladať samo. Ak zaváha, spýtajte sa: „Čo sme povedali ako prvé?“ Až keď si nevie pomôcť, pripomeňte prvý obrázok a nechajte ho dokončiť zvyšok. Nakoniec pochváľte konkrétne: „Výborne, celý rad bol správny!“', 1, 5, 7, 4, '{"type":"memory_sequence","intro":"Obrázky sa ti ukážu len na chvíľku. Dobre sa pozeraj a potom ich poukladaj presne v rovnakom poradí!","revealMsPerItem":1500,"items":[{"sequence":["🐶","🍎"],"distractors":["🐱","⚽"],"hint":"Ktorý obrázok sa ukázal ako prvý — zvieratko alebo jedlo?"},{"sequence":["🌞","🚗"],"distractors":["🌙","🚲"],"hint":"Skús si obrázky povedať nahlas ako riekanku. Čím sa začínala?"},{"sequence":["🐟","🌸","⭐"],"distractors":["🐸","🍄"],"hint":"Čo sa objavilo ako prvé? Začni od neho a pokračuj ďalej."},{"sequence":["🎈","🐰","🍌"],"distractors":["🧸","🦆"],"hint":"Predstav si, že obrázky sú malý príbeh. Kto v ňom bol prvý?"},{"sequence":["🏠","☂️","🍓"],"distractors":["🌳","🐝"],"hint":"Zavri na chvíľku oči a skús rad vidieť v hlave. Čo bolo na začiatku?"}]}'::jsonb, true),
('wm-zapamataj-poradie-2', 'working_memory', 'interactive', 'Zapamätaj si poradie — dlhšie rady', 'Rozširovanie rozsahu vizuálnej sekvenčnej pamäti na 3 – 4 prvky s distraktormi. Posilňuje udržanie sériového poradia a odolnosť voči interferencii, podporuje stratégiu verbálneho opakovania.', 'Pred začiatkom povedzte: „Skús si obrázky potichu opakovať, kým sa na ne pozeráš.“ Stratégiu raz predveďte nahlas: „slnko — auto — pes, slnko — auto — pes“. Počas ukladania nezasahujte. Ak si dieťa poradie pomýli, spýtajte sa: „Čím sa rad začínal?“ a nechajte ho opraviť sa samo. Prvý obrázok prezraďte, až keď si dieťa naozaj nevie pomôcť. Po každom rade oceňte snahu, nielen výsledok.', 2, 6, 9, 5, '{"type":"memory_sequence","intro":"Rady obrázkov sú teraz dlhšie. Skús si ich potichu opakovať, kým sa pozeráš — potom ich poukladaj v správnom poradí!","revealMsPerItem":1200,"items":[{"sequence":["🐶","🌞","🍎"],"distractors":["🐱","🚗"],"hint":"Skús si rad zopakovať potichu ako pesničku. Čo bolo prvé?"},{"sequence":["⭐","🐸","🎈"],"distractors":["🌸","🐟"],"hint":"Jeden z obrázkov svieti na oblohe — bol na začiatku, alebo na konci radu?"},{"sequence":["🚂","🐘","🌼","🔑"],"distractors":["🚁","🦁"],"hint":"Rozdeľ si rad na dve dvojice. Ktorá dvojica bola prvá?"},{"sequence":["🎩","🐢","🍇","👟"],"distractors":["🧦","🐍"],"hint":"Predstav si obrázky ako príbeh: čo sa v ňom objavilo najskôr?"},{"sequence":["🍦","🐥","🌈","⚽"],"distractors":["🍩","🐙"],"hint":"Zopakuj si rad ešte raz v hlave. Ktorý obrázok ti utiekol?"}]}'::jsonb, true),
('wm-zapamataj-poradie-3', 'working_memory', 'interactive', 'Zapamätaj si poradie — majstrovská výzva', 'Náročné sekvencie 4 – 6 prvkov rozvíjajú kapacitu vizuálnej pracovnej pamäti a metakognitívne stratégie zapamätávania (verbálne opakovanie, vizualizácia, zoskupovanie do dvojíc).', 'Ukážte dieťaťu stratégiu zoskupovania: „Zapamätaj si obrázky po dvojiciach — najprv prvé dve, potom ďalšie.“ Počas ukladania nezasahujte a nechajte dieťa pracovať vlastným tempom. Ak sa pomýli, povedzte pokojne: „Skoro! Ktorá časť radu ti utiekla?“ a doprajte mu nový pokus. Po každom rade spolu zhodnoťte: „Čo ti dnes pomohlo zapamätať si obrázky?“ Chyba je súčasť tréningu — dôležitý je plán, nie dokonalosť.', 3, 7, 10, 6, '{"type":"memory_sequence","intro":"Toto je výzva pre majstrov pamäti! Rady sú dlhé, tak si ich rozdeľ na menšie časti — a do toho!","revealMsPerItem":1000,"items":[{"sequence":["🐶","🍎","🌞","⚽"],"distractors":["🐱","🍌","🚗"],"hint":"Rozdeľ si rad na dve dvojice. Ktorá dvojica bola prvá?"},{"sequence":["🌸","🐟","🎈","⭐"],"distractors":["🐸","🌙","🧸"],"hint":"Skús si rad povedať nahlas ako riekanku. Čím sa začínala?"},{"sequence":["🚗","🐰","🍓","🌳","🔑"],"distractors":["🚲","🐝","🍪"],"hint":"Predstav si obrázky ako cestu: čo ťa na nej čakalo najprv a čo potom?"},{"sequence":["🦁","🌈","🍕","🐢","⛵"],"distractors":["🐙","🍇","🎁"],"hint":"Ktoré zvieratko bolo na začiatku? Začni od neho a spomínaj ďalej."},{"sequence":["🌞","🐶","🍎","⭐","🚗","🎈"],"distractors":["🐱","🌸","🍌"],"hint":"Šesť obrázkov je veľa — rozdeľ si ich na tri dvojice. Ako znela prvá?"}]}'::jsonb, true),
('wm-pexeso-1', 'working_memory', 'interactive', 'Pexeso so zvieratkami', 'Pexeso rozvíja vizuálno-priestorovú pracovnú pamäť a zámerné zapamätávanie polohy podnetov; súčasne podporuje udržiavanie pozornosti a striedanie v hre.', 'Hrajte spolu a striedajte sa v ťahoch. Každú otočenú kartu spolu nahlas pomenujte: „mačka!“ — pomenovanie pomáha pamäti. Keď dieťa hľadá pár, spýtajte sa: „Kde sme už mačku videli?“ a doprajte mu čas. Správnu kartu nikdy neukazujte; radšej zúžte výber otázkou: „Bola v hornom alebo dolnom rade?“ Na konci spolu spočítajte páry a pochváľte, čo sa dieťaťu podarilo zapamätať.', 1, 5, 7, 5, '{"type":"pairs","intro":"Zvieratká sa poschovávali do kartičiek — vždy dve rovnaké. Dobre si pamätaj, kde sa ktoré skrýva, a nájdi všetky páry!","pairs":["🐶","🐱","🐰","🐸","🦁"],"columns":5}'::jsonb, true),
('wm-pexeso-2', 'working_memory', 'interactive', 'Veľké ovocné pexeso', 'Náročnejšia verzia pexesa (8 párov) zvyšuje pamäťovú záťaž a nároky na systematické prehľadávanie poľa a priebežnú aktualizáciu obsahu pracovnej pamäti.', 'Pred hrou sa dohodnite na pláne: „Budeme otáčať karty pekne po poriadku, aby sa nám ľahšie pamätalo.“ Každú otočenú kartu nahlas pomenujte. Ak dieťa dlhšie nenachádza pár, spýtajte sa: „Ktoré ovocie si pamätáš najlepšie? Skús nájsť jeho druhú kartu.“ Nesúrte ho a neukazujte správne karty. Na konci sa spolu porozprávajte, čo dieťaťu pomáhalo — plán je pri pamäti rovnako dôležitý ako šťastie.', 2, 6, 10, 8, '{"type":"pairs","intro":"Ovocie sa pomiešalo! Nájdi vždy dve rovnaké kartičky. Dobre si pamätaj, kde čo leží — kariet je tentoraz naozaj veľa.","pairs":["🍎","🍌","🍓","🍇","🍉","🍒","🍋","🍐"],"columns":4}'::jsonb, true),
('wm-opakuj-odzadu-2', 'working_memory', 'speech', 'Povedz to odzadu', 'Reprodukcia radu čísel a slov v opačnom poradí (backward span) zaťažuje centrálnu exekutívu — dieťa musí podnety súčasne podržať v pamäti a mentálne preusporiadať.', 'Povedzte: „Zahráme sa na opačnú ozvenu. Ja poviem slová a ty ich povieš odzadu.“ Najprv hru predveďte: „Poviem: oko — nos. Odzadu je to: nos — oko.“ Čítajte pomaly a zreteľne, medzi slovami urobte krátku pauzu. Ak sa dieťaťu nedarí, položte na stôl za každé slovo jeden gombík a ukážte prstom, že začíname od posledného. Chybu neopravujte hneď — najprv sa spýtajte: „Ktoré slovo bolo posledné?“', 2, 6, 10, 5, '{"type":"speech_items","intro":"Zahráme sa na kúzelnú ozvenu — všetko, čo počuješ, povieš odzadu!","items":[{"text":"2 – 5","emoji":"🔢","tip":"Správne odzadu: 5 – 2. Čítajte pomaly, medzi číslami urobte krátku pauzu."},{"text":"8 – 3","emoji":"🔢","tip":"Správne odzadu: 3 – 8."},{"text":"mama – dom","emoji":"💬","tip":"Správne odzadu: dom – mama."},{"text":"slnko – ryba","emoji":"💬","tip":"Správne odzadu: ryba – slnko."},{"text":"4 – 9 – 1","emoji":"🔢","tip":"Správne odzadu: 1 – 9 – 4. Tri čísla sú ťažšie — ak treba, prečítajte rad ešte raz."},{"text":"6 – 2 – 7","emoji":"🔢","tip":"Správne odzadu: 7 – 2 – 6."},{"text":"pes – kvet – lopta","emoji":"💬","tip":"Správne odzadu: lopta – kvet – pes."},{"text":"med – zima – vlak","emoji":"💬","tip":"Správne odzadu: vlak – zima – med. Ak treba, pomôžte gombíkmi: jeden za každé slovo, začnite od posledného."}]}'::jsonb, true),
('wm-zopakuj-vetu-3', 'working_memory', 'speech', 'Zopakuj vetu', 'Opakovanie viet so stúpajúcou dĺžkou (4 – 12 slov) mapuje kapacitu verbálnej pracovnej pamäti a morfosyntaktické spracovanie; je citlivým ukazovateľom vývinových jazykových ťažkostí.', 'Povedzte: „Prečítam ti vetu iba raz. Dobre počúvaj a potom ju povieš presne tak isto.“ Čítajte pokojne, prirodzeným tempom, bez slabikovania. Ak dieťa vetu zmení, nehovorte, čo bolo zle — prečítajte ju ešte raz a nechajte nový pokus. Pri dlhých vetách pomôžte rozdelením: prečítajte prvú polovicu, dieťa ju zopakuje, potom druhú a nakoniec celú vetu. Oceňte každé presné zopakovanie: „Ani slovko ti neušlo!“', 3, 7, 10, 6, '{"type":"speech_items","intro":"Dobre počúvaj a zopakuj vetu presne tak, ako ju počuješ — ani slovko navyše, ani slovko menej!","items":[{"text":"Mačka spí na okne.","emoji":"🐱","tip":"Sledujte predložku „na“ — deti ju často vynechajú."},{"text":"Malý psík behá po záhrade.","emoji":"🐶","tip":"Pozor na predložku „po“ a na slovo „malý“ — veta musí zaznieť celá."},{"text":"Mama kúpila v obchode čerstvé rožky.","emoji":"🥐","tip":"Sledujte predložku „v“ a poradie slov — „čerstvé rožky“, nie naopak."},{"text":"V lete sa radi kúpeme v jazere.","emoji":"🏊","tip":"Veta má dve predložky „v“ — obe musia zaznieť. Pozor aj na slovko „sa“."},{"text":"Babka nám upiekla koláč s jablkami a orechmi.","emoji":"🥧","tip":"Sledujte predložku „s“ a poradie: najprv jablká, potom orechy."},{"text":"Ráno si obujem topánky a bežím rýchlo do školy.","emoji":"👟","tip":"Pozor na slovko „si“ a predložku „do“. Časti vety sa nesmú vymeniť."},{"text":"V sobotu pôjdeme s rodinou na výlet do vysokých hôr.","emoji":"⛰️","tip":"Veta má až štyri predložky: „v“, „s“, „na“, „do“ — sledujte, či zaznejú všetky."},{"text":"Keď vonku prší, sadneme si k oknu a spolu kreslíme veselé obrázky.","emoji":"🌧️","tip":"Dlhá veta — sledujte spojku „keď“, predložku „k“ a či z vety nič nevypadlo."}]}'::jsonb, true)
